insert into public.semasa_posts (id, idea_id, stream, domain, angle, lang, hook, text, citation, slides, date, slot, status, flags, hard_flags, published, posted_at, archived_at, created_at) values ('67046979-cf41-5b03-a71d-c4e4f742745a'::uuid, 'ee1d694b-e839-5fc9-a61b-288c8cced9fb'::uuid, 'regulab', 'makanan', null, 'bm', 'Eksekutif Halal dalam borang, tapi bila produk anda tular malam Jumaat, siapa jawab?', '{"bm":{"instagram":"Bahagian Pengurusan Halal JAKIM dah jelaskan: syarikat pengeluar kena ada Sistem Jaminan Halal (SJH) yang berfungsi, bukan sekadar nama Eksekutif Halal atas borang. Jawatankuasa Halal Dalaman ini yang sepatutnya pantau perolehan bahan mentah dan proses pengeluaran dari hari pertama, bukan lepas dapat sijil sahaja.\n\nSebab bila isu tular, benda yang selamatkan jenama anda bukan sijil di dinding pejabat. Ia rekod perolehan bahan mentah, nama pembekal, nombor sijil halal pembekal, tarikh luput sijil itu, dan anda kena boleh keluarkan semua ini dalam masa dua jam bila customer atau media tanya.\n\nSyarikat yang ada Eksekutif Halal berfungsi, dengan rekod dikemaskini setiap batch, boleh jawab pada hari yang sama. Syarikat yang letak nama je dalam MYeHALAL akan ambil masa lebih seminggu untuk cari balik dokumen pembekal. Seminggu itu cukup lama untuk customer tukar jenama.\n\nKalau anda sendiri tak pasti di mana rekod perolehan bahan mentah terkini disimpan sekarang, itu soalan pertama untuk audit dalaman anda.","facebook":"JAKIM dah tegaskan: Eksekutif Halal dan Jawatankuasa Halal Dalaman bukan hiasan borang MYeHALAL. Bila produk tular, yang selamatkan jenama bukan sijil di dinding, tapi rekod perolehan bahan mentah, nombor sijil pembekal dan tarikh luputnya, yang boleh dikeluarkan dalam dua jam.\n\nSyarikat dengan Eksekutif Halal berfungsi jawab hari yang sama. Syarikat yang cuma namakan orang dalam borang ambil masa seminggu, dan seminggu itu cukup untuk jenama hilang kepercayaan.","threads":"Eksekutif Halal bukan nama dekorasi dalam borang MYeHALAL. Bila produk tular, yang selamatkan anda ialah rekod perolehan bahan mentah, boleh keluar dalam dua jam, ada nombor sijil pembekal dan tarikh luput. Kalau ambil masa seminggu untuk cari, jenama dah tenggelam."},"en":{"instagram":"JAKIM''s halal management division has been clear on this: producers need a functioning Halal Assurance System, not just an Eksekutif Halal''s name sitting on a form. The Jawatankuasa Halal Dalaman is supposed to monitor raw material sourcing and production from day one, not only after the certificate is issued.\n\nBecause when your product goes viral for the wrong reason, what saves your brand is not the certificate framed on the wall. It''s the sourcing record: supplier name, supplier''s halal certificate number, its expiry date, and you need to be able to pull all this within two hours when a customer or journalist asks.\n\nCompanies with a functioning Eksekutif Halal and records updated per batch can answer the same day. Companies that just put a name on the MYeHALAL form will take more than a week digging up supplier documents. That week is long enough for customers to switch brands.\n\nIf you don''t know right now where your current sourcing records are kept, that''s the first question for your internal audit.","facebook":"JAKIM has said it plainly: Eksekutif Halal and the internal halal committee aren''t paperwork decoration. When your product trends for the wrong reason, what saves the brand isn''t the certificate on the wall, it''s the sourcing record, supplier certificate number and expiry, retrievable in two hours.\n\nCompanies with a working Eksekutif Halal answer same day. Companies that only named someone on a form take a week, and a week is long enough for a brand to die.","threads":"Eksekutif Halal isn''t a name for decoration on a MYeHALAL form. When a product trends badly, what saves you is a sourcing record you can pull in two hours, supplier cert number and expiry included. If it takes a week to find, the brand is already gone."}}'::jsonb, 'JAKIM, Bahagian Pengurusan Halal, “Penjelasan Isu Serbuk Kari Jenama Baba’s dan Alagappa’s” (Isu-Isu Tular Halal); Manual Prosedur Pensijilan Halal Malaysia (Domestik) 2020, Klausa 20 — Sistem Jaminan Halal, 20(2)–20(4)', '[]'::jsonb, '2026-09-26'::date, '13:00', 'draft', '[{"hard":true,"where":"Caption (facebook)","msg":"implies an inside contact (''orang dalam'')"},{"hard":true,"where":"Post","msg":"instagram needs an image"}]'::jsonb, 2, '{}'::jsonb, null, null, '2026-09-20T16:47:12.187Z'::timestamptz) on conflict (id) do nothing;  -- 0fo60fu831 (draft)
insert into public.semasa_posts (id, idea_id, stream, domain, angle, lang, hook, text, citation, slides, date, slot, status, flags, hard_flags, published, posted_at, archived_at, created_at) values ('a81bc4cb-1590-5a66-badc-3a3446df6cc5'::uuid, null, 'linkedin', null, 'C', 'en', 'A textile standard just borrowed its safety limits from the cosmetics annex, and that is worth noticing.', '{"bm":{"linkedin":"Kenya dan Komuniti Afrika Timur edarkan draf standard untuk disposable wet wipes (G/TBT/N/KEN/2117, diedarkan 24 September 2026), difailkan di bawah ICS 59.080.01, Textiles.\n\nTapi senarai dokumen rujukan standard ini sendiri memetik ARS 1524-1/2/3 (senarai bahan dilarang, terhad dan dibenarkan), ISO 23674 (had merkuri dalam kosmetik) dan lima standard ISO lain untuk ujian mikrobiologi kosmetik.\n\nJadi tajuk klasifikasi Textiles tidak bermakna produk itu terlepas daripada had bahan dan mikrobiologi gred kosmetik. Rujukan normatif standard itu sendiri yang menentukan, bukan ICS code di muka depan.\n\nUntuk sesiapa yang failkan produk berasaskan klasifikasi tunggal, rujukan silang dalam standard yang dipakai kena disemak dulu, bukan sekadar tajuk dan kod ICS.\n\nTingkap maklum balas tutup 23 November 2026.\n\nSources: Kenya/East African Community, Draft African Standard, Disposable wet wipes - Specification, G/TBT/N/KEN/2117, WTO TBT notification, distributed 24 Sept 2026\n\n#RegulatoryAffairs #WTOTBT #CosmeticSafety #StandardsCompliance"},"en":{"linkedin":"A textile standard just borrowed its safety limits from the cosmetics annex, and that is worth noticing.\n\nKenya and the East African Community notified a draft standard for disposable wet wipes (G/TBT/N/KEN/2117, distributed 24 September 2026), filed under ICS 59.080.01, Textiles.\n\nIts own reference document list cites ARS 1524-1/2/3 (prohibited, restricted and permitted substance lists), ISO 23674 (mercury limits in cosmetics) and five further ISO standards for cosmetic microbiology test methods.\n\nA Textiles classification heading does not mean the product escapes cosmetic-grade substance and microbiology limits. The standard''s own normative references decide that, not the ICS code on the cover page.\n\nIf you file a product outside cosmetic scope on the strength of a classification heading alone, check the reference list the standard actually cites first.\n\nComment window closes 23 November 2026.\n\nSources: Kenya/East African Community, Draft African Standard, Disposable wet wipes - Specification, G/TBT/N/KEN/2117, WTO TBT notification, distributed 24 Sept 2026\n\n#RegulatoryAffairs #WTOTBT #CosmeticSafety #StandardsCompliance"}}'::jsonb, 'Kenya/East African Community, Draft African Standard, Disposable wet wipes - Specification, G/TBT/N/KEN/2117, WTO TBT notification, distributed 24 Sept 2026', '[]'::jsonb, '2026-09-30'::date, '19:00', 'draft', '[]'::jsonb, 0, '{}'::jsonb, null, null, '2026-09-25T14:05:00.000Z'::timestamptz) on conflict (id) do nothing;  -- 18nkigiz1e (draft)
insert into public.semasa_posts (id, idea_id, stream, domain, angle, lang, hook, text, citation, slides, date, slot, status, flags, hard_flags, published, posted_at, archived_at, created_at) values ('7d049af4-98b7-5253-918a-76c892e568bf'::uuid, null, 'linkedin', null, 'A', 'en', 'A regulator just pulled three products for being cosmetics that acted like something else.', '{"bm":{"linkedin":"ANVISA, pihak berkuasa kesihatan Brazil, keluarkan Resolucao 3.714/2026 (Diario Oficial da Uniao, 21 September 2026) yang mengharamkan pengilangan, pengedaran, pengiklanan, penjualan dan penggunaan tiga produk keluaran Klug Industria Quimica e de Cosmeticos: Smart Exo Skin Pro, Smart Hyaluclar Micro dan Smart Mesoeffect Micro.\n\nSebab yang dinyatakan bukan bahan berbahaya. Ketiga-tiga produk didaftarkan sebagai kosmetik sedangkan ciri-cirinya mendorong penggunaan invasif.\n\nUntuk chemist yang formulate produk delivery yang menembusi lapisan kulit, macam microneedling-adjacent atau mesotherapy-style, ini poin sempadan yang sama macam formula Kligman di sisi kosmetik topikal. Yang tentukan klasifikasi bukan kategori yang dipilih brand pada borang notifikasi. Yang tentukan ialah mekanisme delivery dan kedalaman penembusan yang dimaksudkan.\n\nSemak mekanisme produk anda terhadap definisi kosmetik topikal sebelum failkan, bukan selepas regulator tanya soalan itu.\n\nSources: ANVISA (Agencia Nacional de Vigilancia Sanitaria, Brazil), Resolucao 3.714/2026, Diario Oficial da Uniao, published 21 Sept 2026\n\n#RegulatoryAffairs #CosmeticClassification #ANVISA #Cosmetovigilance"},"en":{"linkedin":"ANVISA, Brazil''s health regulator, issued Resolucao 3.714/2026 (Diario Oficial da Uniao, 21 September 2026), banning the manufacture, distribution, advertising, sale and use of three products from Klug Industria Quimica e de Cosmeticos: Smart Exo Skin Pro, Smart Hyaluclar Micro and Smart Mesoeffect Micro.\n\nThe stated reason is not a hazardous ingredient. All three were registered as cosmetics while their characteristics induced invasive use.\n\nFor chemists formulating delivery systems meant to act past the skin barrier, microneedling-adjacent or mesotherapy-style products, this is the same boundary question the Kligman formula case makes on the topical side. What decides classification is not the category a brand ticks on the notification form. It is the delivery mechanism and the intended penetration depth.\n\nCheck your product''s mechanism against the topical cosmetic definition before filing, not after a regulator asks the question for you.\n\nSources: ANVISA (Agencia Nacional de Vigilancia Sanitaria, Brazil), Resolucao 3.714/2026, Diario Oficial da Uniao, published 21 Sept 2026\n\n#RegulatoryAffairs #CosmeticClassification #ANVISA #Cosmetovigilance"}}'::jsonb, 'ANVISA (Agencia Nacional de Vigilancia Sanitaria, Brazil), Resolucao 3.714/2026, Diario Oficial da Uniao, published 21 Sept 2026', '[]'::jsonb, '2026-10-01'::date, '06:00', 'draft', '[]'::jsonb, 0, '{}'::jsonb, null, null, '2026-09-25T14:05:00.000Z'::timestamptz) on conflict (id) do nothing;  -- 1hoyw2saan (draft)
insert into public.semasa_posts (id, idea_id, stream, domain, angle, lang, hook, text, citation, slides, date, slot, status, flags, hard_flags, published, posted_at, archived_at, created_at) values ('b187a88d-e436-5d8e-866d-50d02425742b'::uuid, '2557008a-4bcc-5884-8931-5637c0b6cf8d'::uuid, 'regulab', 'halal_my', null, 'bm', 'Setiap kali artwork baharu siap, soalan sama muncul: logo halal kena hijau ke?', '{"bm":{"instagram":"Setiap kali pereka pembungkusan hantar artwork baharu, soalan ini pasti timbul: logo halal wajib hijau ke supaya nampak ''betul''?\n\nBukan. Tak ada mana-mana peraturan yang kunci warna logo halal Malaysia kepada satu warna sahaja. Industri memang diberi ruang guna logo pelbagai warna, disesuaikan dengan warna latar pembungkusan produk, supaya logo tetap jelas dan tidak calar dengan reka bentuk keseluruhan.\n\nYang tak boleh berubah ialah spesifikasi logo itu sendiri: bentuk, nisbah saiz dan elemen di dalamnya. Ini yang ditetapkan oleh Pihak Berkuasa Berwibawa selari dengan Klausa 40(2), Manual Prosedur Pensijilan Halal Malaysia (Domestik) 2020. Warna fleksibel, tapi bentuk dan nisbah bukan tempat untuk kreativiti pereka grafik.\n\nSebab tu bila artwork masuk untuk kelulusan, rujuk klausa ni, bukan pendapat pembekal percetakan atau ''biasa client lain buat macam ni''. Ramai kena hantar semula artwork sebab logo diperkecilkan lebih daripada nisbah dibenarkan, bukan sebab warnanya salah.","facebook":"Soalan yang sama datang setiap kali artwork pembungkusan baharu siap: logo halal mesti hijau ke?\n\nTak. Warna logo halal Malaysia boleh disesuaikan dengan pembungkusan produk. Yang tetap ialah bentuk, nisbah dan elemen logo, ikut Klausa 40(2), Manual Prosedur Pensijilan Halal Malaysia (Domestik) 2020.\n\nJadi bila pereka anda tanya pasal warna logo, rujuk klausa ni, bukan pendapat pembekal percetakan.","threads":"Logo halal mesti hijau? Tak. Warna boleh ikut pembungkusan anda, bentuk dan nisbah logo yang tetap, ikut Klausa 40(2) MPPHM 2020. Rujuk klausa tu, bukan pembekal percetakan."},"en":{"instagram":"Every time a new packaging artwork gets finalised, the same question comes up: does the halal logo have to be green to be ''correct''?\n\nNo. There is no rule locking Malaysia''s halal logo to one colour. Industry players are given room to use the logo in different colours matched to their packaging''s background, so the logo stays visible and doesn''t clash with the design.\n\nWhat stays fixed is the logo''s specification itself: its shape, size ratio and internal elements. This is set by the Competent Authority under Clause 40(2), Manual Prosedur Pensijilan Halal Malaysia (Domestik) 2020. Colour is flexible, shape and ratio are not up for creative interpretation.\n\nSo when artwork goes in for approval, cite this clause, not a printing vendor''s opinion or ''that''s what other clients did''. Most resubmissions happen because the logo was shrunk below the allowed ratio, not because the colour was wrong.","facebook":"The same question comes up with every new packaging artwork: does the halal logo have to be green?\n\nNo. Colour can match your packaging. What''s fixed is the logo''s shape, ratio and elements, under Clause 40(2), Manual Prosedur Pensijilan Halal Malaysia (Domestik) 2020.\n\nSo when your designer asks about logo colour, point them to this clause, not a printing vendor''s opinion.","threads":"Halal logo must be green? No. Colour can match your packaging, shape and ratio stay fixed under Clause 40(2) MPPHM 2020. Cite the clause, not your printer''s opinion."}}'::jsonb, 'Manual Prosedur Pensijilan Halal Malaysia (Domestik) 2020, Klausa 40(2) — warna logo boleh disesuaikan selagi tidak mengubah spesifikasi logo; JAKIM, “Penjelasan Isu Kempen Tukar Warna Logo Halal Malaysia” (Isu-Isu Tular Halal)', '[]'::jsonb, '2026-09-27'::date, '08:00', 'scheduled', '[{"hard":true,"where":"Post","msg":"instagram needs an image"}]'::jsonb, 1, '{"facebook":{"at":"2026-09-27 06:29 MYT","dueAt":"2026-09-27T08:00:00+08:00","id":"6ab84723ccccb9429c3bf92a","mode":"customScheduled","route":"buffer-release","status":"scheduled","via":"ws.regulab Studio"},"instagram":{"at":"2026-09-27 06:29 MYT","dueAt":"2026-09-27T08:00:00+08:00","id":"6ab8472a0f79a37c5d3cfd64","mode":"customScheduled","route":"buffer-release","status":"scheduled","via":"ws.regulab Studio"},"threads":{"at":"2026-09-27 06:29 MYT","dueAt":"2026-09-27T08:00:00+08:00","id":"6ab8472d3d66d464e5bf058d","mode":"customScheduled","route":"buffer-release","status":"scheduled","via":"ws.regulab Studio"}}'::jsonb, null, null, '2026-09-20T16:16:29.209Z'::timestamptz) on conflict (id) do nothing;  -- 2dyp6dqpyw (scheduled)
insert into public.semasa_posts (id, idea_id, stream, domain, angle, lang, hook, text, citation, slides, date, slot, status, flags, hard_flags, published, posted_at, archived_at, created_at) values ('9b1186e1-d739-59e2-90e0-e7deefc53a4e'::uuid, '61e2a8cc-9a6b-5944-ac26-e5e6818ed2d7'::uuid, 'regulab', 'halal_my', null, 'bm', 'Semua barang kat rak tu bersijil halal, jadi kedai runcit tu automatik "halal" juga? Tak begitu.', '{"bm":{"instagram":"Ramai anggap kalau kebanyakan produk kat kedai runcit atau minimarket bersijil halal, kedai itu sendiri jadi \"halal\". Ini silap konsep yang JAKIM sendiri dah betulkan dalam laman Isu-Isu Tular Halal rasmi mereka.\n\nPremis jenis peruncitan, iaitu kedai runcit dan minimarket, pada asasnya bukan pemegang Sijil Pengesahan Halal Malaysia (SPHM). JAKIM tidak pernah mengeluarkan pensijilan halal untuk konsep peruncitan itu sendiri.\n\nSPHM disijilkan ikut skim: produk, premis makanan (foodservice), rumah sembelihan, dan beberapa skim lain. Peruncitan bukan salah satu daripadanya.\n\nJadi bila anda masuk kedai runcit, soalan yang patut ditanya bukan \"kedai ni halal ke tak\". Soalan sebenar: produk yang anda beli tu ada sijil sendiri ke tak, dan macam mana kedai itu asingkan barang halal dan tidak halal kat rak yang sama.\n\nUntuk pengusaha yang bekalkan produk ke kedai runcit atau minimarket, perkara ini penting juga. Sijil yang sah tu melekat pada produk anda punya nama, bukan pada reputasi kedai tempat ia dijual.","facebook":"Ramai anggap kalau kebanyakan produk kat kedai runcit bersijil halal, kedai itu sendiri jadi \"halal\". JAKIM dah betulkan ini dalam laman Isu-Isu Tular Halal rasmi: premis peruncitan bukan pemegang SPHM, dan JAKIM tak pernah sijilkan konsep peruncitan.\n\nSPHM disijilkan ikut skim: produk, premis makanan, rumah sembelihan. Peruncitan bukan salah satunya.\n\nSoalan yang patut ditanya bukan \"kedai ni halal ke tak\", tapi produk yang anda beli tu ada sijil sendiri ke tak, dan macam mana kedai itu asingkan barang di rak yang sama.","threads":"Kedai runcit bukan pemegang SPHM walaupun rak dia penuh produk bersijil halal. JAKIM dah confirm ni dalam laman Isu-Isu Tular Halal: pensijilan halal ikut skim, produk atau premis makanan, bukan skim peruncitan. Soalan yang betul: produk tu ada sijil sendiri ke tak."},"en":{"instagram":"A lot of people assume that if most products on a grocery store''s shelves carry a halal certificate, the store itself is \"halal\". JAKIM corrected this misconception directly on their official Isu-Isu Tular Halal page.\n\nRetail-type premises, meaning grocery stores and minimarkets, are fundamentally not holders of the Sijil Pengesahan Halal Malaysia (SPHM). JAKIM has never issued halal certification for the retail concept itself.\n\nSPHM is certified by scheme: product, food premise (foodservice), slaughterhouse, and a few others. Retail is not one of them.\n\nSo when you walk into a grocery store, the question isn''t \"is this shop halal\". The real question is whether the specific product you''re buying has its own certificate, and how the shop separates halal and non-halal items on the same shelf.\n\nFor businesses supplying grocery stores or minimarkets, this matters too. A valid certificate belongs to your product''s name, not to the reputation of the shop it''s sold in.","facebook":"Many assume that if most products in a grocery store carry halal certificates, the store itself is \"halal\". JAKIM has clarified this on their official Isu-Isu Tular Halal page: retail premises are not SPHM holders, and JAKIM has never certified the retail concept itself.\n\nSPHM is certified by scheme: product, food premise, slaughterhouse. Retail isn''t one of them.\n\nThe question to ask isn''t \"is this shop halal\", it''s whether the product you''re buying has its own certificate, and how the shelf is managed.","threads":"A grocery store isn''t an SPHM holder even if every product on its shelf is halal certified. JAKIM confirmed this on their Isu-Isu Tular Halal page: certification runs by scheme, product or food premise, not a retail scheme. The right question is whether the product itself is certified."}}'::jsonb, 'JAKIM, Bahagian Pengurusan Halal, “Penjelasan Isu Pengendalian Pork Slice di Sebuah Premis Runcit” (Isu-Isu Tular Halal); Manual Prosedur Pensijilan Halal Malaysia (Domestik) 2020, Klausa 4 — sembilan skim pensijilan, peruncitan bukan antaranya', '[]'::jsonb, '2026-10-04'::date, '08:00', 'draft', '[{"hard":true,"where":"Post","msg":"instagram needs an image"}]'::jsonb, 1, '{}'::jsonb, null, null, '2026-09-21T16:48:04.420Z'::timestamptz) on conflict (id) do nothing;  -- 41oikyb71y (draft)
insert into public.semasa_posts (id, idea_id, stream, domain, angle, lang, hook, text, citation, slides, date, slot, status, flags, hard_flags, published, posted_at, archived_at, created_at) values ('75e9c7e8-f744-5800-8980-7fbb538b0571'::uuid, '5c818ff3-b3d8-595a-9844-98e35fb6913f'::uuid, 'linkedin', null, 'B', 'en', 'Many brand owners running through Indonesian contract manufacturers assume the maklon''s halal certificate settles the halal question for their finished cosmetic. That assumption is about to get more expensive.', '{"bm":{"linkedin":"Ramai brand owner yang guna kilang kontrak (maklon) di Indonesia anggap sijil halal maklon itu sudah cukup untuk produk kosmetik siap mereka. Andaian itu bakal jadi lebih mahal untuk disemak semula.\n\nBPJPH Indonesia telah notify draf Keputusan Kepala BPJPH tentang garis panduan pelaksanaan SJPH (Sistem Jaminan Produk Halal) untuk perkhidmatan pemprosesan, dokumen WTO G/TBT/N/IDN/197, diedarkan 24 September 2026. Medan products covered menyenaraikan makanan, minuman, ubat dan kosmetik yang dihasilkan atau diproses melalui perkhidmatan pemprosesan, termasuk maklon, dapur kongsi, pemprosesan air dan pengisaran. Keperluan SJPH dikenakan ke atas pelaku perniagaan (business actor), bukan hanya kilang.\n\nIni satu pergeseran daripada mensijilkan produk siap kepada mensijilkan langkah pemprosesan itu sendiri. Satu sijil di maklon tidak automatik lepaskan kewajipan SJPH brand owner sendiri bila garis panduan ini kuat kuasa.\n\nTarikh penerimaan dan tarikh kuat kuasa masih to be determined. Tingkap maklum balas tutup 23 November 2026.\n\n[SAHKAN: kewajipan SJPH tepat ke atas pelaku perniagaan yang guna perkhidmatan maklon di bawah draf ini -- draf 16 muka surat Bahasa Indonesia belum dibaca, hanya medan notifikasi WTO tersedia]\n\nSources: G/TBT/N/IDN/197 (WTO TBT notification, diedarkan 24/09/2026)"},"en":{"linkedin":"Many brand owners running through Indonesian contract manufacturers assume the maklon''s halal certificate settles the halal question for their finished cosmetic. That assumption is about to get more expensive.\n\nIndonesia''s BPJPH has notified a draft Decision on SJPH implementation guidelines for processing services, WTO document G/TBT/N/IDN/197, distributed 24 September 2026. The products covered field lists food, beverages, drugs and cosmetics produced or processed through processing services, explicitly naming maklon, shared kitchens, water processing and milling. The SJPH obligation sits with the business actor, not just the facility.\n\nThat is a shift from certifying the finished product to certifying the processing step itself. One certificate at the maklon does not automatically discharge the brand owner''s own SJPH obligation once this guideline lands.\n\nAcceptance date and entry into force are still to be determined. The comment window closes 23 November 2026.\n\nSources: G/TBT/N/IDN/197 (WTO TBT notification, distributed 24/09/2026)"}}'::jsonb, 'G/TBT/N/IDN/197, WTO TBT notification, distributed 24/09/2026, comments close 23/11/2026', '[]'::jsonb, '2026-09-27'::date, '19:00', 'draft', '[]'::jsonb, 0, '{}'::jsonb, null, null, '2026-09-25T02:35:54.821Z'::timestamptz) on conflict (id) do nothing;  -- 4e5w8ompvq (approved)
insert into public.semasa_posts (id, idea_id, stream, domain, angle, lang, hook, text, citation, slides, date, slot, status, flags, hard_flags, published, posted_at, archived_at, created_at) values ('ce1e4754-6a4e-5713-ab48-c6a9a7abead7'::uuid, '9fde3c0d-3321-5976-800f-3d3d32cc6294'::uuid, 'regulab', 'kajian_kes', null, 'bm', 'Sanitizer kena tarik balik sebab methanol lebih had. Ramai tuduh formula. Salah sasaran.', '{"bm":{"instagram":"Bila NPRA batalkan notifikasi hand sanitizer sebab methanol melebihi had, reaksi pertama ramai ialah salahkan formula. Sebenarnya bukan situ masalahnya. Methanol bukan bahan yang syarikat tambah sengaja, ia masuk melalui ethanol gred industri atau denatured alcohol yang tak disaring betul di peringkat pembekal. Ini kegagalan raw material, bukan kegagalan lab anda.\n\nUnder ASEAN Cosmetic Directive Annex III (Release 2023-1, 5 Jun 2023), methanol (CAS 67-56-1) dibenarkan sebagai denaturant untuk ethanol dan isopropyl alcohol pada maksimum 5%, dikira atas peratusan ethanol dan isopropyl alcohol itu sendiri. Malaysia pakai Annex ini terus melalui rejim notifikasi kosmetik NPRA. Jadi bila pembekal cakap ''gred kosmetik'', itu bukan spec, itu jualan.\n\nApa yang patut ada dalam fail setiap batch:\n1. Spesifikasi raw material yang state had methanol secara jelas, rujuk terus kepada Annex III, bukan tafsiran pembekal.\n2. CoA daripada pembekal untuk setiap penghantaran, bukan sekali untuk semua penghantaran.\n3. Sekurang-kurangnya satu ujian pengesahan bebas setiap kali tukar atau tambah pembekal baharu.\n\nBila pihak berkuasa ambil sampel dari pasaran, formula anda tak selamatkan anda. Rekod yang selamatkan anda.","facebook":"NPRA batalkan notifikasi hand sanitizer sebab methanol melebihi had. Ramai fikir masalah formula, sebenarnya masalah raw material dari pembekal, ethanol gred industri yang tak disaring betul.\n\nASEAN Cosmetic Directive Annex III (Release 2023-1, 5 Jun 2023) benarkan methanol sebagai denaturant maksimum 5% daripada kandungan ethanol/isopropyl alcohol. Malaysia pakai had ini melalui notifikasi NPRA. ''Gred kosmetik'' yang pembekal sebut tu bukan spec rasmi.\n\nFail batch anda kena ada: spec raw material yang rujuk Annex III terus, CoA setiap penghantaran, dan ujian pengesahan bebas untuk pembekal baharu. Rekod yang selamatkan anda bila sample diambil, bukan formula.","threads":"NPRA batalkan sanitizer sebab methanol lebih had. Bukan salah formula, salah raw material dari pembekal. ACD Annex III benarkan methanol sebagai denaturant max 5% daripada ethanol/isopropyl alcohol, Malaysia pakai had ni melalui notifikasi NPRA. Spec anda kena rujuk Annex III terus, bukan tafsiran ''gred kosmetik'' pembekal. CoA setiap penghantaran, ujian pengesahan untuk pembekal baharu. Rekod yang selamatkan anda, bukan formula."},"en":{"instagram":"When NPRA cancels a hand sanitizer notification because methanol exceeds the limit, the first reaction is always to blame the formula. That is the wrong place to look. Methanol is not an ingredient anyone adds on purpose, it enters through industrial grade ethanol or denatured alcohol that was not screened properly at the supplier level. This is a raw material failure, not a lab failure.\n\nUnder the ASEAN Cosmetic Directive Annex III (Release 2023-1, 5 June 2023), methanol (CAS 67-56-1) is permitted as a denaturant for ethanol and isopropyl alcohol at a maximum of 5%, calculated on the ethanol and isopropyl alcohol content itself. Malaysia adopts this Annex directly through the NPRA cosmetic notification regime. So when a supplier says ''cosmetic grade'', that is a sales term, not a spec.\n\nWhat your batch file needs: a raw material spec that states the methanol limit clearly, referencing Annex III directly and not a supplier''s interpretation of it. A CoA from the supplier for every shipment, not one for the whole relationship. At least one independent verification test whenever you switch or add a new supplier.\n\nWhen the authority pulls a sample off the shelf, your formula does not save you. Your records do.","facebook":"NPRA cancelled a hand sanitizer notification over methanol exceeding the limit. Everyone assumes it is a formula problem, it is actually a raw material problem, industrial grade ethanol that was not screened properly.\n\nASEAN Cosmetic Directive Annex III (Release 2023-1, 5 June 2023) allows methanol as a denaturant up to 5% of the ethanol/isopropyl alcohol content. Malaysia applies this limit through NPRA notification. ''Cosmetic grade'' as suppliers use it is not an official spec.\n\nYour batch file needs a raw material spec referencing Annex III directly, a CoA for every shipment, and independent verification testing for new suppliers. Records save you when samples get pulled, not the formula.","threads":"NPRA pulled a sanitizer notification over methanol exceeding the limit. Not a formula failure, a supplier raw material failure. ACD Annex III allows methanol as denaturant up to 5% of ethanol/isopropyl alcohol, Malaysia applies this through NPRA notification. Your spec needs to reference Annex III directly, not a supplier''s ''cosmetic grade'' claim. CoA per shipment, verification testing for new suppliers. Records save you, not the formula."}}'::jsonb, 'ASEAN Cosmetic Directive Annex III, Release 2023-1, 5 Jun 2023; Kenyataan Media KKM, Putrajaya, 21 Ogos 2026 — Chomel Hand Sanitizer, NOT221001118K, kelompok BN111025/BN01026/BN061225', '[]'::jsonb, '2026-09-30'::date, '08:00', 'draft', '[{"hard":true,"where":"Post","msg":"instagram needs an image"}]'::jsonb, 1, '{}'::jsonb, null, null, '2026-09-20T16:14:37.380Z'::timestamptz) on conflict (id) do nothing;  -- 4lum61obrk (draft)
insert into public.semasa_posts (id, idea_id, stream, domain, angle, lang, hook, text, citation, slides, date, slot, status, flags, hard_flags, published, posted_at, archived_at, created_at) values ('be84f8c6-e73f-5fbd-a8e9-456523fe99ca'::uuid, '25d3cb46-b9ac-5235-817d-5c792a0fe268'::uuid, 'linkedin', null, 'F', 'en', 'A cell line lighting up ERα is not a woman using sunscreen getting cancer.', '{"bm":{"linkedin":"Ramai baca ''benzophenone-3 aktifkan ERα/E2F1/RPA3 dalam sel kanser payudara'' sebagai bukti sunscreen punca kanser. Bukan begitu.\n\nKajian baharu dalam Ecotoxicology and Environmental Safety guna model sel kanser payudara luminal A, dedahkan kepada benzophenone-3, dan jejak satu laluan signalling: estrogen receptor alpha (ERα) aktifkan E2F1, E2F1 pacu RPA3, RPA3 pacu proliferation. Itu mechanism dalam dish sahaja. Bukan epidemiology, bukan clinical trial pada manusia yang guna UV filter.\n\nIni bahagian yang chemist patut fikir dalam-dalam. Benzophenone-3 sudah pun clear review oleh CIR dan SCCS. Clearance itu satu status, bukan verdict yang kekal selama-lamanya. Logik sama macam CIR re-review untuk ascorbic acid: scheduled cycle yang buka semula fail tu. Kali ini trigger berbeza, satu mechanistic paper baharu bagi assessors data endocrine-pathway baharu untuk ditimbang bila fail dibuka semula.\n\nMechanistic data tak boleh terus overturn opinion lama. Ia bina case file untuk bila-bila masa opinion tu diuji semula.\n\nSources: Liu M, Liu J, Cheng R, et al. Ecotoxicology and Environmental Safety, 15 Sept 2026. [SAHKAN: DOI belum dijumpai, senarai isu jurnal disemak setakat tarikh draf]\n\n#RegulatoryAffairs #Cosmetovigilance #UVFilters #SCCS #CosmeticScience"},"en":{"linkedin":"People keep reading ''benzophenone-3 activates ERα/E2F1/RPA3 in breast cancer cells'' as proof sunscreen causes cancer. It is not that.\n\nThe new paper in Ecotoxicology and Environmental Safety used a luminal breast cancer cell model, exposed it to benzophenone-3, and traced a signalling chain: estrogen receptor alpha switches on E2F1, E2F1 drives RPA3, RPA3 drives proliferation. That is a mechanism in a dish. It is not epidemiology and it is not a human clinical trial on UV filter use.\n\nHere is the part worth sitting with as a chemist. Benzophenone-3 already cleared review by CIR and SCCS. That clearance is a status, not a verdict fixed in time. Same logic as ascorbic acid''s CIR re-review: a scheduled cycle pulled that file back open. This time the trigger is different, a fresh mechanistic paper gives assessors new endocrine-pathway data to weigh whenever the file reopens.\n\nMechanistic data does not overturn a prior opinion by itself. It builds the case file for the next time that opinion gets tested.\n\nSources: Liu M, Liu J, Cheng R, et al. Ecotoxicology and Environmental Safety, 15 Sept 2026. [SAHKAN: DOI not located, checked journal issue listing available as of draft date]\n\n#RegulatoryAffairs #Cosmetovigilance #UVFilters #SCCS #CosmeticScience"}}'::jsonb, 'Liu M, Liu J, Cheng R, et al., Ecotoxicology and Environmental Safety, 15 Sept 2026', '[]'::jsonb, '2026-09-28'::date, '19:00', 'draft', '[]'::jsonb, 0, '{}'::jsonb, null, null, '2026-09-25T06:49:30.942Z'::timestamptz) on conflict (id) do nothing;  -- 58xv1coulu (draft)
insert into public.semasa_posts (id, idea_id, stream, domain, angle, lang, hook, text, citation, slides, date, slot, status, flags, hard_flags, published, posted_at, archived_at, created_at) values ('1fdf236d-d326-5421-96b2-fdb03e964b7c'::uuid, '546d86c8-ca8c-5fbd-a2d1-d50537a46332'::uuid, 'regulab', 'halal_my', null, 'bm', 'Logo badan pensijilan yang diiktiraf pada produk pelik? Itu bukan salah badan tu, itu salah syarikat yang letak logo.', '{"bm":{"instagram":"Ramai nampak logo badan pensijilan halal luar negara pada sesuatu produk yang label dia sendiri sebut ada unsur tidak halal, terus buat kesimpulan badan pensijilan tu longgar atau tak boleh dipercayai. Ni salah faham yang kerap berlaku.\n\nJAKIM mengiktiraf BADAN pensijilan, bukan produk. Pengiktirafan tu bermaksud badan tersebut punya sistem dan kredibiliti yang JAKIM terima. Tapi sijil sebenar untuk sesuatu produk dikeluarkan secara berasingan, per produk, per kilang. Satu badan boleh sijilkan ratusan produk, dan tak semua produk syarikat yang sama automatik masuk senarai tu.\n\nJadi bila anda nampak logo halal pada produk yang buat anda tertanya-tanya, soalan yang patut ditanya bukan ''kenapa badan ni sijilkan benda macam ni''. Soalan yang betul: ''produk ni memang ada dalam senarai sijil badan tu ke tidak''. Kalau logo ada tapi produk tak wujud dalam senarai, itu penyalahgunaan logo oleh syarikat pengeluar, bukan kegagalan badan pensijilan.\n\nUntuk pengimport: sebelum bawa masuk atau edarkan produk berlogo halal, semak status sijil produk tu sendiri. Jangan bergantung pada logo je.","facebook":"Logo badan pensijilan halal luar negara yang diiktiraf JAKIM pada sesuatu produk tak bermakna produk tu disijilkan. Pengiktirafan JAKIM diberi pada badan, bukan pada setiap produk yang bawa logonya. Sijil sebenar dikeluarkan per produk, per kilang, dan boleh disemak.\n\nJadi bila nampak logo pada produk yang pelik, soalan betul bukan ''kenapa badan tu sijilkan ni'' tapi ''produk ni ada dalam senarai sijil badan tu ke tidak''. Kalau tiada, itu salah guna logo oleh syarikat, bukan kelemahan badan pensijilan.\n\nUntuk pengimport: semak status sijil produk, bukan status pengiktirafan badan sahaja.","threads":"Logo badan halal luar negara yang diiktiraf JAKIM pada produk tak bermakna produk tu disijilkan. Pengiktirafan tu untuk badan, bukan setiap produk yang bawa logonya. Sijil sebenar per produk, per kilang, dan boleh disemak. Kalau produk tak ada dalam senarai sijil, itu salah guna logo, bukan kegagalan badan. Semak produk, bukan cuma logo."},"en":{"instagram":"People see a recognised foreign halal certification body''s logo on a product whose own label mentions a non-halal ingredient, and jump to ''this certification body is unreliable''. That is the wrong read.\n\nJAKIM''s recognition is given to the certification BODY, not to every product carrying its logo. Recognition means JAKIM accepts that body''s system and credibility. But the actual certificate for a specific product is issued separately, per product, per factory. One recognised body can certify hundreds of products, and not every product from the same manufacturer is automatically on that list.\n\nSo when you see a halal logo on a product that looks off, the question is not ''why did this body certify something like this''. The right question is ''is this exact product actually on that body''s certified list''. If the logo is there but the product is not on the list, that is logo misuse by the manufacturer, not a failure of the certification body.\n\nFor importers: before you bring in or distribute a product with a halal logo, check the certificate status of that specific product. Don''t take the logo at face value.","facebook":"A recognised foreign halal certification body''s logo on a product does not mean that product is certified. JAKIM''s recognition applies to the body, not to every product bearing its logo. The actual certificate is issued per product, per factory, and it is checkable.\n\nSo when a logo shows up on a product that looks wrong, the right question isn''t ''why did this body certify this''. It''s ''is this product actually on that body''s certified list''. If it isn''t, that''s logo misuse by the manufacturer, not a certification body failure.\n\nFor importers: check the product''s own certificate status, not just the body''s recognition status.","threads":"A recognised foreign halal body''s logo on a product doesn''t mean that product is certified. JAKIM recognises the BODY, not every product carrying its logo. Certificates are issued per product, per factory, and checkable. If a product isn''t on that body''s list, it''s logo misuse, not a certification body failure."}}'::jsonb, 'JAKIM, Senarai Badan Pensijilan Halal Luar Negara yang Diiktiraf (halal.gov.my): pengiktirafan diberikan kepada badan, pengesahan status sijil sesuatu produk perlu disemak berasingan melalui badan berkenaan atau saluran rasmi JAKIM', '[]'::jsonb, '2026-10-04'::date, '13:00', 'draft', '[{"hard":true,"where":"Post","msg":"instagram needs an image"}]'::jsonb, 1, '{}'::jsonb, null, null, '2026-09-21T16:47:18.588Z'::timestamptz) on conflict (id) do nothing;  -- 67vvy7a7p5 (draft)
insert into public.semasa_posts (id, idea_id, stream, domain, angle, lang, hook, text, citation, slides, date, slot, status, flags, hard_flags, published, posted_at, archived_at, created_at) values ('5b45dde6-7cf9-509e-8399-414b955e90fc'::uuid, 'bd54cf12-c119-528c-b441-ba1c4c13b07f'::uuid, 'regulab', 'sains_kosmetik', null, 'bm', '1 daripada 10 pewarna rambut ''PPD-free'' betul-betul bebas amina reaktif silang. 9 lagi tidak.', '{"bm":{"instagram":"9 daripada 10 pewarna rambut yang label ''bebas PPD'' rupanya masih ada amina reaktif silang yang boleh cetus alah sama.\n\nKajian retrospektif dalam jurnal Contact Dermatitis, atas 56 pesakit yang alah kepada PPD di UK, uji 10 jenama pewarna rambut yang letak label ''PPD-free''. Hasilnya, cuma 1 jenama yang betul-betul bebas daripada semua amina reaktif silang seperti para-toluenediamine. 27% pesakit yang diuji terhadap para-toluenediamine tunjuk cross-reactivity, walaupun produk yang mereka guna tak pernah sebut PPD dalam INCI.\n\nIni bukan soal jenama tipu. Masalahnya di label itu sendiri: ''bebas PPD'' cuma bermaksud PPD sendiri tak ada dalam formula. Ia tak jamin amina lain dalam keluarga kimia yang sama, yang boleh cetus tindak balas alah silang, turut tiada.\n\nUntuk jenama kosmetik yang nak buat dakwaan ''bebas [bahan]'' pada label di Malaysia, semakan komposisi patut sandar pada data ujian penuh terhadap kumpulan amina berkaitan, bukan sekadar pastikan satu nama tak muncul dalam senarai INCI. Notifikasi kosmetik NPRA memang minta INCI lengkap, tapi INCI lengkap bukan jaminan bebas cross-reactivity kalau dakwaan yang dibuat sempit macam ini.\n\nKalau anda formulate atau notify produk pewarna rambut, ini titik yang patut disemak semula sebelum dakwaan itu naik ke label.","facebook":"Kajian dalam jurnal Contact Dermatitis (UK) uji 10 pewarna rambut berlabel ''PPD-free'' atas 56 pesakit alah PPD. Cuma 1 yang betul-betul bebas semua amina reaktif silang macam para-toluenediamine. 27% pesakit tunjuk cross-reactivity pada para-toluenediamine walaupun produk tak sebut PPD.\n\nLabel ''bebas PPD'' cuma jamin satu molekul itu tiada, bukan seluruh keluarga amina yang boleh cetus alah sama. Kalau nak buat dakwaan ''bebas [bahan]'', sandarkan pada data ujian penuh, bukan sekadar semakan INCI.","threads":"1 daripada 10 pewarna rambut ''PPD-free'' yang diuji betul-betul bebas amina reaktif silang. 9 lagi masih ada. Kajian Contact Dermatitis (UK), 56 pesakit alah PPD, 27% cross-react dengan para-toluenediamine. Label ''bebas X'' cuma jamin X tiada, bukan seluruh keluarga kimia yang serupa."},"en":{"instagram":"9 out of 10 hair dyes labelled ''PPD-free'' still contain reactive cross-linking amines that can trigger the same allergy.\n\nA retrospective study in Contact Dermatitis, on 56 patients allergic to PPD in the UK, tested 10 hair dye brands carrying a ''PPD-free'' label. Only 1 was genuinely free of all reactive cross-linking amines such as para-toluenediamine. 27% of patients tested against para-toluenediamine showed cross-reactivity, even when the product they used never listed PPD in its INCI.\n\nThis is not about brands lying. The problem sits in the claim itself. ''PPD-free'' only means PPD itself is absent from the formula. It says nothing about other amines in the same chemical family that can trigger a cross-allergic reaction.\n\nFor cosmetic brands making a ''free from [ingredient]'' claim in Malaysia, the composition review should be backed by full testing data on the related amine group, not just confirmation that one name is missing from the INCI list. NPRA cosmetic notification does require a complete INCI, but a complete INCI does not guarantee freedom from cross-reactivity if the claim itself is written this narrow.\n\nIf you formulate or notify a hair dye product, this is the point to re-check before that claim goes on the label.","facebook":"A study in Contact Dermatitis (UK) tested 10 hair dyes labelled ''PPD-free'' on 56 PPD-allergic patients. Only 1 was genuinely free of all reactive cross-linking amines like para-toluenediamine. 27% of patients cross-reacted to para-toluenediamine even when the product never listed PPD.\n\n''PPD-free'' only guarantees one named molecule is absent, not the whole amine family that can trigger the same allergy. A ''free from X'' claim needs full testing data behind it, not just an INCI check.","threads":"Only 1 out of 10 ''PPD-free'' hair dyes tested was truly free of reactive cross-linking amines. The other 9 weren''t. Contact Dermatitis study (UK), 56 PPD-allergic patients, 27% cross-reacted to para-toluenediamine. A ''free from X'' label only guarantees X, not the rest of its chemical family."}}'::jsonb, 'Contact Dermatitis (journal), University Hospital Southampton retrospective study on PPD-allergic patients, published 22 Sept 2026 [SAHKAN: volume/issue/DOI belum disahkan]', '[]'::jsonb, '2026-09-28'::date, '21:00', 'draft', '[{"hard":true,"where":"Post","msg":"instagram needs an image"}]'::jsonb, 1, '{}'::jsonb, null, null, '2026-09-24T02:17:40.790Z'::timestamptz) on conflict (id) do nothing;  -- 7j3z8pjeze (draft)
insert into public.semasa_posts (id, idea_id, stream, domain, angle, lang, hook, text, citation, slides, date, slot, status, flags, hard_flags, published, posted_at, archived_at, created_at) values ('ac0c5615-f651-53db-9728-a5ed06207ae7'::uuid, '3b52b651-566f-5bb8-9820-fd65921f7615'::uuid, 'regulab', 'makanan', null, 'bm', 'Rempah kari tular sebab video WhatsApp, tapi titik kawalan sebenar langsung bukan di situ.', '{"bm":{"instagram":"JAKIM dah keluarkan penjelasan rasmi dalam laman Isu-Isu Tular Halal berkenaan video dan mesej WhatsApp yang mendakwa rempah kari dan kurma import dari India dihasilkan guna najis dan air kencing lembu. Penemuan JAKIM: produk yang dipersoalkan itu tidak memiliki SPHM, dan tiada juga sijil daripada badan pensijilan halal luar negara yang diiktiraf.\n\nItu penemuan sebenar, bukan tuduhan yang tular tu.\n\nUntuk premis makanan, ini bahagian yang penting dan selalu tercicir: bahan yang tiada sijil diiktiraf bukan automatik haram. Statusnya cuma tak dapat disahkan. Dua perkara tu berbeza. Tapi bila premis anda bersijil, bahan yang statusnya tak dapat disahkan pun sama je kesannya, tak boleh guna.\n\nAnda boleh ada SPHM tergantung depan kaunter dan tetap gagal audit sebab satu tin rempah kari di dapur belakang tiada dokumen sokongan. Auditor tak tanya pasal rasa. Dia tanya sijil dan asal bahan, sampai ke pembekal.\n\nDue diligence bermula dari invois pembekal, bukan dari label produk siap. Kalau pembekal tak boleh tunjukkan sijil halal yang sah atau nombor MYeHALAL, bahan tu keluar dari senarai bahan mentah premis bersijil, walaupun ia sendiri tak haram.","facebook":"JAKIM dah jelaskan dalam laman Isu-Isu Tular Halal: rempah kari dan kurma import yang dipersoalkan dalam video tular tu tidak memiliki SPHM mahupun sijil badan pensijilan halal luar negara yang diiktiraf.\n\nItu penemuan sebenarnya, bukan dakwaan najis yang tular.\n\nUntuk premis makanan: bahan tanpa sijil diiktiraf bukan automatik haram, statusnya cuma tak dapat disahkan. Tapi premis bersijil tetap tak boleh guna. SPHM depan kaunter tak selamatkan anda kalau satu bahan di dapur belakang tiada dokumen.","threads":"JAKIM: rempah kari import yang dipersoalkan dalam video tular tu tiada SPHM, tiada sijil luar negara diiktiraf. Itu penemuan sebenar, bukan dakwaan najis yang tular.\n\nTiada sijil diiktiraf bukan automatik haram, cuma tak dapat disahkan. Tapi premis bersijil tetap tak boleh guna bahan macam tu."},"en":{"instagram":"JAKIM published an official clarification on its Isu-Isu Tular Halal page about the Facebook video and WhatsApp messages claiming that imported Indian curry spices and dates were produced using cow dung and urine. JAKIM''s actual finding: the questioned products carried no SPHM and no certificate from a recognised foreign halal certification body.\n\nThat is the real finding, not the claim that went viral.\n\nFor food premises, here is the part that keeps getting missed: an ingredient without a recognised certificate is not automatically haram. Its status simply cannot be verified. Those are two different things. But once your premise holds SPHM, an ingredient with unverifiable status gets treated the same way as one that fails, it cannot be used.\n\nYou can have SPHM hanging at the counter and still fail an audit because one tin of curry powder in the back kitchen has no supporting documentation. The auditor is not asking about taste. They are asking for certificates, traced back to the supplier.\n\nDue diligence starts at the supplier invoice, not the finished product label. If a supplier cannot produce a valid halal certificate or a MYeHALAL number, that ingredient comes off the list for a certified premise, even if it is not haram on its own.","facebook":"JAKIM''s own clarification on the Isu-Isu Tular Halal page: the imported curry spices and dates questioned in the viral video carried no SPHM and no certificate from a recognised foreign halal body.\n\nThat''s the actual finding, not the dung and urine claim that went around on WhatsApp.\n\nFor food premises: no recognised certificate does not mean haram, it means unverified. But a certified premise still can''t use it. SPHM at the counter won''t save you if one ingredient in the back kitchen has no paper trail.","threads":"JAKIM: the curry spices in that viral video carried no SPHM, no recognised foreign halal cert. That''s the actual finding, not the dung claim.\n\nNo cert doesn''t mean haram. It means unverified. A certified premise still can''t use it though."}}'::jsonb, 'JAKIM, laman rasmi Isu-Isu Tular Halal, halal.gov.my (dibaca 19 Sept 2026)', '[]'::jsonb, '2026-10-01'::date, '21:00', 'draft', '[{"hard":true,"where":"Post","msg":"instagram needs an image"}]'::jsonb, 1, '{}'::jsonb, null, null, '2026-09-21T16:49:20.459Z'::timestamptz) on conflict (id) do nothing;  -- 89lp8ictml (draft)
insert into public.semasa_posts (id, idea_id, stream, domain, angle, lang, hook, text, citation, slides, date, slot, status, flags, hard_flags, published, posted_at, archived_at, created_at) values ('03be668d-f484-590c-81df-f16a72f897ef'::uuid, 'bf75efb0-d00e-5f0a-8f24-de09d03f6d31'::uuid, 'linkedin', null, 'E', 'en', 'Same brand name, two Safety Gate alerts, two weeks apart. That is not a repeat, it is two files.', '{"bm":{"linkedin":"Bila satu jenama muncul dua kali dalam EU Safety Gate dalam masa yang singkat, orang terus anggap ini satu masalah yang gagal diselesaikan. Selalunya itu silap.\n\nSafety Gate bagi reference number berasingan untuk setiap notifying member state, setiap product reference atau batch, dan setiap risk finding. Satu jenama pewarna rambut boleh kena dua alert yang tak berkaitan sebab dua importer berbeza letak dua formulasi berbeza di dua pasaran berbeza, dan setiap authority notify secara berasingan.\n\nUntuk oxidative hair dye, chemical risk yang biasa berulang ialah restricted colorant macam para-phenylenediamine (PPD) yang melebihi had concentration untuk kegunaan tersebut, atau ingredient yang tak ada dalam positive list di Annex III, EU Cosmetic Products Regulation.\n\nBahagian yang selalu terlepas pandang: selesaikan corrective action untuk alert pertama tak bermakna alert kedua pun selesai. Setiap notifying authority nak confirmation sendiri yang batch tersebut sudah ditarik dari pasaran mereka. Layan sebagai dua fail, dua response, dua paper trail.\n\n[SAHKAN: nombor alert Safety Gate sebenar dan tarikh untuk chemical risk finding pewarna rambut ini -- hanya sahkan struktur umum satu alert per notification di portal Safety Gate]\n\nSources: EU Safety Gate portal (alert structure); Regulation (EC) No 1223/2009, Annex III.\n\n#EUSafetyGate #CosmeticRegulation #HairDyeSafety #RegulatoryAffairs #ASEANcosmetics"},"en":{"linkedin":"When a brand name shows up twice on the EU Safety Gate portal in quick succession, the instinct is to read it as one problem the company failed to fix. That is usually wrong.\n\nSafety Gate assigns a distinct alert reference per notifying member state, per product reference or batch, per risk finding. A hair dye brand can rack up two unrelated alerts because two different importers placed two different formulations on two different national markets, and each authority notified independently.\n\nFor oxidative hair dyes, the recurring chemical risk is usually a restricted colorant such as para-phenylenediamine (PPD) exceeding the concentration limit set for that use, or an ingredient absent from the positive list in Annex III of the EU Cosmetic Products Regulation.\n\nThe part people miss: closing out corrective action on the first alert does not close the second. Each notifying authority wants its own confirmation that the specific batch is withdrawn from its own market. Treat them as two files, two responses, two paper trails.\n\n[SAHKAN: exact Safety Gate alert numbers and dates for this specific hair dye chemical risk finding -- confirmed only the general alert-per-notification structure on the Safety Gate portal]\n\nSources: EU Safety Gate portal (alert structure); Regulation (EC) No 1223/2009, Annex III.\n\n#EUSafetyGate #CosmeticRegulation #HairDyeSafety #RegulatoryAffairs #ASEANcosmetics"}}'::jsonb, 'EU Safety Gate portal (alert structure); Regulation (EC) No 1223/2009, Annex III', '[]'::jsonb, '2026-10-02'::date, '06:00', 'draft', '[]'::jsonb, 0, '{}'::jsonb, null, null, '2026-09-26T02:21:06.961Z'::timestamptz) on conflict (id) do nothing;  -- 9ea70ojjhh (draft)
insert into public.semasa_posts (id, idea_id, stream, domain, angle, lang, hook, text, citation, slides, date, slot, status, flags, hard_flags, published, posted_at, archived_at, created_at) values ('25bf606f-77a4-5a7b-89f2-3d81785284cb'::uuid, '8989b030-af3a-563b-9aa6-d63623e1e4f5'::uuid, 'regulab', 'farmaseutikal', null, 'bm', 'Kod ''LM10'' pada label bukan bukti lemak babi. Itu cuma kod dalaman pembekal.', '{"bm":{"instagram":"Setiap kali isu ''kod rahsia lemak babi'' ni tular balik, ceritanya sama: seseorang jumpa kod macam LM10 dalam senarai ramuan, sebar dakwaan ia tanda lemak babi disamarkan, dan rangkaian F&B besar kena tuduh guna bahan haram.\n\nFakta yang jarang dibaca: kod macam LM10 bukan kod ramuan halal-haram antarabangsa. Ia kod dalaman pembekal untuk rujukan batch atau kategori produk, lebih kurang macam kod SKU dalam gudang anda sendiri. Ia berbeza daripada nombor E, yang memang ada standard antarabangsa dan memang perlu disemak sumbernya satu-satu.\n\nJAKIM sendiri dah jelaskan isu ini, dan premis-premis yang dituduh kekal sebagai pemegang sijil SPHM yang sah. Bukan isu baru, cuma tular semula sebab kod nampak asing kepada orang awam, dan itu memang bahan mentah paling senang untuk content tular.\n\nUntuk pengeluar yang guna kod dalaman pada raw material: fail halal anda kena ada satu muka surat yang terjemahkan setiap kod kepada nama kimia penuh dan sumbernya. Bila soalan datang, anda tak boleh cari dulu, anda kena tunjuk terus.\n\nKod ramuan bukan bukti. Bukti ada pada dokumentasi sumber, bukan pada rupa kod tu menakutkan orang atau tidak.","facebook":"Isu ''kod rahsia lemak babi'' macam LM10 tular balik dari semasa ke semasa. Fakta: kod macam ini bukan kod ramuan halal-haram antarabangsa, ia cuma kod rujukan dalaman pembekal, beza dengan nombor E yang memang ada standard antarabangsa.\n\nJAKIM dah jelaskan isu ini dan premis yang dituduh kekal pemegang SPHM yang sah.\n\nPengajaran untuk pengeluar: kalau anda guna kod dalaman pada raw material, fail halal anda kena boleh terjemahkan setiap kod kepada nama kimia dan sumbernya, dalam satu muka surat, bila-bila masa diminta.","threads":"Kod macam ''LM10'' bukan bukti lemak babi. Ia kod dalaman pembekal, bukan kod antarabangsa. JAKIM dah jelaskan, premis yang dituduh kekal pemegang SPHM sah. Kalau anda pengeluar guna kod dalaman pada raw material, fail halal anda kena boleh terjemah setiap kod kepada nama kimia dan sumber, terus, bila diminta."},"en":{"instagram":"Every time the ''secret pork fat code'' story resurfaces, the pattern is the same: someone spots a code like LM10 in an ingredient list, claims it marks hidden pork fat, and a major F&B chain gets accused of using non-halal material.\n\nWhat gets missed: codes like LM10 are not an international halal or haram ingredient code. They are internal supplier codes for batch or product category reference, similar to an SKU code in your own warehouse. That is different from E numbers, which do follow an international standard and do need their source verified individually.\n\nJAKIM has addressed this directly, and the premises named remain valid SPHM certificate holders. It is not a new issue, it just resurfaces because unfamiliar codes look suspicious to the public, which is exactly why it is such easy viral material.\n\nFor manufacturers using internal codes on raw material: your halal file needs one page that translates every code to its full chemical name and source. When the question comes, you should not be searching, you should be pointing.\n\nAn ingredient code is not evidence. Evidence lives in source documentation, not in how alarming a code looks.","facebook":"The ''secret pork fat code'' story (LM10 and similar) resurfaces periodically. Fact: codes like this are not international halal/haram codes, they are internal supplier reference codes, unlike E numbers which do carry an international standard.\n\nJAKIM has addressed this and the premises named remain valid SPHM holders.\n\nLesson for manufacturers: if you use internal codes on raw material, your halal file needs to translate every code to its chemical name and source, on one page, on demand.","threads":"Codes like ''LM10'' are not proof of pork fat. They''re internal supplier codes, not an international standard. JAKIM addressed it, the premises named remain valid SPHM holders. If you''re a manufacturer using internal codes on raw material, your halal file needs to translate each one to chemical name and source, on the spot."}}'::jsonb, 'JAKIM, kenyataan rasmi mengenai dakwaan kod ''LM10'' (sejak 11 Feb 2017, disahkan semula 19 Sept 2026)', '[]'::jsonb, '2026-09-26'::date, '21:00', 'draft', '[{"hard":true,"where":"Post","msg":"instagram needs an image"}]'::jsonb, 1, '{}'::jsonb, null, null, '2026-09-21T15:36:29.079Z'::timestamptz) on conflict (id) do nothing;  -- anbeesr4pn (draft)
insert into public.semasa_posts (id, idea_id, stream, domain, angle, lang, hook, text, citation, slides, date, slot, status, flags, hard_flags, published, posted_at, archived_at, created_at) values ('78ffdb37-d747-5e8e-91d7-188879ca48e1'::uuid, '0005f91a-31aa-5192-8c7b-fe29778724a6'::uuid, 'regulab', 'halal_my', null, 'bm', 'Tiada logo halal pada perniagaan tu bukan bermakna produk dia haram. Undang-undang jalan arah bertentangan.', '{"bm":{"instagram":"Tiada Sijil Pengesahan Halal Malaysia (SPHM) bukan bermakna produk itu haram. Ini silap paling biasa yang saya nampak dalam perbualan pasal halal kebelakangan ini.\n\nSPHM ialah pensijilan sukarela. Syarikat yang tak memohon tak melakukan sebarang kesalahan sebab tak ada sijil. Kesalahan sebenar berjalan arah bertentangan: mendakwa \"halal\", atau paparkan logo halal, tanpa sijil sah yang boleh kena tindakan di bawah Akta Perihal Dagangan 2011.\n\nUntuk pengusaha: kalau anda belum ada SPHM, jangan tulis perkataan halal pada label atau signage, jangan letak logo, jangan guna ayat yang buat orang sangka anda bersijil. Anda masih boleh nyatakan bahan-bahan anda secara jujur, itu bukan kesalahan.\n\nUntuk pengguna: takde sijil bermaksud takde maklumat yang disahkan pihak berkuasa, bukan bukti kandungan haram.\n\nDi bawah Perintah Perihal Dagangan (Perakuan dan Penandaan Halal) 2011, hanya JAKIM dan Majlis Agama Islam Negeri (MAIN) boleh perakukan status halal. Third party di media sosial, tak kira berapa ramai followers, bukan pihak berkuasa memperaku di bawah Perintah itu.","facebook":"Tiada SPHM bukan bermakna haram. Ramai silap faham benda ni.\n\nSPHM ialah pensijilan sukarela, jadi syarikat yang tak memohon tak buat salah. Kesalahan sebenar ialah mendakwa halal atau guna logo halal tanpa sijil sah, di bawah Akta Perihal Dagangan 2011.\n\nHanya JAKIM dan MAIN boleh perakukan status halal, bukan pihak ketiga di media sosial.","threads":"Tiada SPHM bukan bermakna haram. Ia pensijilan sukarela. Kesalahan sebenar ialah dakwa halal atau guna logo tanpa sijil sah, bukan sebaliknya. Hanya JAKIM & MAIN boleh perakukan halal."},"en":{"instagram":"No Halal Certificate does not mean a product is haram. This is the most common mix-up I keep seeing in halal discussions lately.\n\nHalal certification in Malaysia is voluntary. A business that never applied has not broken any law by not having one. The actual offence runs the other way: claiming \"halal\", or displaying a halal logo, without a valid certificate, which can attract action under the Trade Descriptions Act 2011.\n\nFor founders: if you don''t have MYeHALAL certification, don''t put the word halal on your label or signage, don''t use the logo, and avoid phrasing that implies you''re certified. You can still state your ingredients honestly, that''s not an offence.\n\nFor consumers: no certificate means no verified information from the authority, not proof that something is haram.\n\nUnder the Trade Descriptions (Certification and Marking of Halal) Order 2011, only JAKIM and the State Islamic Religious Councils (MAIN) can certify halal status. Third parties on social media, no matter the following, are not a certifying authority under that Order.","facebook":"No halal certificate does not mean haram. This gets misunderstood constantly.\n\nCertification is voluntary, so not applying is not an offence. Claiming halal or using the logo without a valid cert is the actual offence under the Trade Descriptions Act 2011.\n\nOnly JAKIM and MAIN can certify halal status, not anyone on social media.","threads":"No halal cert doesn''t mean haram. It''s voluntary. The real offence is claiming halal or using the logo without a valid cert, not the absence of one. Only JAKIM and MAIN certify."}}'::jsonb, 'Perintah Perihal Dagangan (Perakuan dan Penandaan Halal) 2011, di bawah Akta Perihal Dagangan 2011', '[]'::jsonb, '2026-09-27'::date, '21:00', 'scheduled', '[{"hard":true,"where":"Post","msg":"instagram needs an image"}]'::jsonb, 1, '{"facebook":{"at":"2026-09-27 06:31 MYT","dueAt":"2026-09-27T21:00:00+08:00","id":"6ab847ba4b4b9f2c1c5a2591","mode":"customScheduled","route":"buffer-release","status":"scheduled","via":"ws.regulab Studio"},"instagram":{"at":"2026-09-27 06:31 MYT","dueAt":"2026-09-27T21:00:00+08:00","id":"6ab847c20f79a37c5d3d1b14","mode":"customScheduled","route":"buffer-release","status":"scheduled","via":"ws.regulab Studio"},"threads":{"at":"2026-09-27 06:31 MYT","dueAt":"2026-09-27T21:00:00+08:00","id":"6ab847c44b4b9f2c1c5a2820","mode":"customScheduled","route":"buffer-release","status":"scheduled","via":"ws.regulab Studio"}}'::jsonb, null, null, '2026-09-20T16:22:06.733Z'::timestamptz) on conflict (id) do nothing;  -- b78nftxyhq (scheduled)
insert into public.semasa_posts (id, idea_id, stream, domain, angle, lang, hook, text, citation, slides, date, slot, status, flags, hard_flags, published, posted_at, archived_at, created_at) values ('a003e3e2-38b7-5481-b76b-ed7969795d6c'::uuid, 'a5b92c94-de76-5c1d-8fa0-5ea95b1cc19e'::uuid, 'regulab', 'kajian_kes', null, 'bm', 'Dua produk ''herba'' dibatalkan NPRA dalam tempoh dua bulan. Sebabnya bukan kunyit.', '{"bm":{"instagram":"Saqa Glowing Turmeric Night Treatment Cream dibatalkan notifikasinya oleh NPRA pada 9 Februari 2026. Sebab: merkuri. Glowing Herbal Treatment pula dibatalkan pada 2 April 2026, sebab merkuri dan betamethasone 17-valerate. Kenyataan Media KKM 9 Februari 2026 dan 2 April 2026\n\nPattern yang kita nampak selepas semak senarai pembatalan NPRA: kedua-dua produk pakai perkataan ''turmeric'' dan ''herbal'' pada label. Tapi bahan yang dikesan bukan kunyit, bahan yang dikesan logam berat dan steroid.\n\nIni bukan kebetulan pemasaran. Kesan cerah yang pantas dan ketara, yang pengguna nampak dalam beberapa hari, datang daripada merkuri dan steroid, bukan daripada kunyit. Nama ''herba'' pada label berfungsi untuk jelaskan kenapa kesan tu laju, supaya pengguna tak syak apa-apa.\n\nKalau anda jenama yang betul-betul guna ekstrak botani, kunyit sebenar, ni bukan cerita orang lain punya masalah. Anda kongsi rak yang sama dengan produk macam ni. Kalau anda tak simpan CoA dan heavy metal test untuk setiap batch, pengguna dan pihak berkuasa tak ada cara nak bezakan jenama anda dengan jenama yang baru kena tarik notifikasi.\n\nSimpan CoA. Uji logam berat setiap batch. Itu je yang boleh cakap bagi pihak anda bila soalan mula datang.","facebook":"Saqa Glowing Turmeric Night Treatment Cream dibatalkan NPRA pada 9 Februari 2026 sebab merkuri. Glowing Herbal Treatment dibatalkan pada 2 April 2026 sebab merkuri dan betamethasone 17-valerate.\n\nKedua-dua guna nama ''turmeric'' dan ''herbal''. Bahan yang dikesan bukan kunyit, tapi logam berat dan steroid. Kesan cerah yang pantas tu datang dari situ, bukan dari kunyit.\n\nKalau anda jenama botani sebenar, anda kongsi rak dengan produk macam ni. Simpan CoA dan uji logam berat setiap batch, itu je yang boleh buktikan beza anda.","threads":"Saqa Turmeric Night Cream: dibatalkan NPRA Feb 2026, sebab merkuri. Glowing Herbal Treatment: dibatalkan April 2026, sebab merkuri dan steroid.\n\nBukan kunyit yang buat kulit cerah pantas. Merkuri yang buat.\n\nKalau jenama anda guna ekstrak botani betul, simpan CoA dan ujian logam berat setiap batch. Rak yang sama, produk yang beza."},"en":{"instagram":"Saqa Glowing Turmeric Night Treatment Cream had its notification cancelled by NPRA on 9 February 2026. Reason: mercury. Glowing Herbal Treatment was cancelled on 2 April 2026, for mercury and betamethasone 17-valerate. Kenyataan Media KKM, 9 February 2026 and 2 April 2026\n\nThe pattern we noticed after checking NPRA''s cancellation list: both products use the words ''turmeric'' and ''herbal'' on the label. But what got detected in testing wasn''t turmeric, it was heavy metal and a steroid.\n\nThis isn''t marketing coincidence. The fast, visible skin lightening effect users saw within days comes from mercury and steroids, not from turmeric. The ''herbal'' branding exists to explain why the effect was so quick, without raising suspicion.\n\nIf you run a brand that genuinely uses botanical extract, real turmeric, this isn''t someone else''s problem. You share shelf space with products like this. Without a CoA and heavy metal testing on every batch, there''s no way for consumers or regulators to tell your brand apart from one that just got its notification pulled.\n\nKeep the CoA. Test heavy metals every batch. That''s the only thing that speaks for you when the questions start.","facebook":"Saqa Glowing Turmeric Night Treatment Cream was cancelled by NPRA on 9 February 2026 for mercury. Glowing Herbal Treatment was cancelled on 2 April 2026 for mercury and betamethasone 17-valerate.\n\nBoth used the words ''turmeric'' and ''herbal''. What got detected wasn''t turmeric, it was heavy metal and a steroid. The fast brightening effect comes from that, not from turmeric.\n\nIf you''re a genuine botanical brand, you share shelf space with products like this. CoA and batch-level heavy metal testing are what prove the difference.","threads":"Saqa Turmeric Night Cream: NPRA cancellation, Feb 2026, mercury. Glowing Herbal Treatment: cancellation, April 2026, mercury and a steroid.\n\nTurmeric doesn''t brighten skin fast. Mercury does.\n\nIf your brand uses real botanical extract, keep a CoA and test heavy metals every batch. Same shelf, different product."}}'::jsonb, 'Senarai Pembatalan Produk Kosmetik Bernotifikasi, NPRA; Kenyataan Media KKM 9 Februari 2026 (Saqa Glowing Turmeric Night Treatment Cream) dan 2 April 2026 (Glowing Herbal Treatment)', '[]'::jsonb, '2026-09-30'::date, '13:00', 'draft', '[{"hard":true,"where":"Post","msg":"instagram needs an image"}]'::jsonb, 1, '{}'::jsonb, null, null, '2026-09-20T16:31:59.508Z'::timestamptz) on conflict (id) do nothing;  -- bov1ioanuk (draft)
insert into public.semasa_posts (id, idea_id, stream, domain, angle, lang, hook, text, citation, slides, date, slot, status, flags, hard_flags, published, posted_at, archived_at, created_at) values ('f86f0065-455f-504c-8493-6bacb01a8f53'::uuid, 'ad202dc1-8820-5e1c-9e5f-540986e9e26b'::uuid, 'linkedin', null, 'F', 'en', '''BPA-free'' on the label tells you about one molecule. It says nothing about the other seven.', '{"bm":{"linkedin":"Satu kajian pilot yang diterbitkan dalam Analytical Methods tahun ini membangunkan kaedah yang lebih sensitif, iaitu MSPE extraction digabung dengan UHPLC-MS/MS, untuk kesan pelbagai bisphenol dan alkylphenol serentak dalam personal care products. Bukan sekadar Bisphenol A. Bisphenol S, Bisphenol F, dan alkylphenol seperti nonylphenol dan octylphenol, yang boleh terhasil sebagai residue daripada surfactant atau emulsifier tertentu, turut disaring dalam kajian yang sama.\n\nIni maksudnya untuk formulator. Dakwaan ''BPA-free'' itu betul tapi sempit skopnya. Ia menjawab satu molekul sahaja daripada satu kumpulan bahan yang berkait secara struktur dan disyaki sama-sama endocrine disrupting. Kalau supplier emulsifier atau surfactant anda tak boleh tunjuk residue profile untuk kumpulan penuh itu, dakwaan pada label anda bukan tipu, cuma tak menjawab soalan yang pengguna sebenarnya fikir dijawab.\n\nKaedah analytical yang lebih baik kini wujud untuk uji seluruh kumpulan, bukan satu molekul sahaja. Logik penilaian regulatory patut catch up dengan itu, begitu juga marketing copy.\n\n[SAHKAN: DOI untuk Sun et al., Analytical Methods 2026]\n\nSources: Sun S, Dong Y, Jin M, Yu E, Shang J, Wang H, Sun L, Analytical Methods, 2026."},"en":{"linkedin":"A pilot study published in Analytical Methods this year built a more sensitive method, MSPE based extraction paired with UHPLC-MS/MS, to detect multiple bisphenols and alkylphenols at once in personal care products. Not just Bisphenol A. Bisphenol S, Bisphenol F, and alkylphenols like nonylphenol and octylphenol, which can turn up as residues from certain surfactants and emulsifiers, were screened in the same run.\n\nHere is what this actually means for formulators. A ''BPA-free'' claim is true and narrow at the same time. It answers one molecule out of a structurally related group that shares suspected endocrine disrupting activity. If your emulsifier or surfactant supplier cannot show you a residue profile for the wider family, the claim on your pack is not lying, it is just not answering the question your customer thinks it answers.\n\nBetter analytical methods exist now to test the group, not the molecule. Regulatory assessment logic should catch up to that, and so should marketing copy.\n\n[SAHKAN: DOI for Sun et al., Analytical Methods 2026]\n\nSources: Sun S, Dong Y, Jin M, Yu E, Shang J, Wang H, Sun L, Analytical Methods, 2026."}}'::jsonb, 'Sun S, Dong Y, Jin M, Yu E, Shang J, Wang H, Sun L, Analytical Methods, 2026 (MSPE-UHPLC-MS/MS method for bisphenols and alkylphenols in personal care products)', '[]'::jsonb, '2026-10-03'::date, '06:00', 'draft', '[]'::jsonb, 0, '{}'::jsonb, null, null, '2026-09-26T18:24:12.591Z'::timestamptz) on conflict (id) do nothing;  -- bwoju4y35z (draft)
insert into public.semasa_posts (id, idea_id, stream, domain, angle, lang, hook, text, citation, slides, date, slot, status, flags, hard_flags, published, posted_at, archived_at, created_at) values ('6b77a7be-b8c6-52fe-b886-832235dc1346'::uuid, '153679fc-ea45-5212-9222-34d15b22e4b1'::uuid, 'linkedin', null, 'F', 'en', '"Formaldehyde-free" keeps getting called marketing spin, but nobody had measured the actual exposure until now.', '{"bm":{"linkedin":"Ramai anggap \"formaldehyde-free keratin treatment\" ni cuma slogan pemasaran untuk dipatahkan, bukan dakwaan untuk diuji. Refleks biasa: glyoxylic acid masih berbau macam Brazilian Blowout lama, jadi mesti masih bebaskan formaldehyde. Refleks tu langkau kimia sebenar.\n\nGlyoxylic acid tak ikut laluan tindak balas yang sama macam sistem methylene glycol/formaldehyde. Kajian dedahan sebenar terbaru dalam Toxicology and Applied Pharmacology sokong ni dengan data dermal exposure sebenar, bukan andaian.\n\nDedahan oxalic acid pengguna daripada produk ni 20 hingga 41 kali lebih rendah berbanding pengambilan diet dan endogenous oxalate harian biasa (22 hingga 45 mg/hari). Untuk penggaya rambut yang buat aplikasi berulang, dedahan lebih 860 kali lebih rendah. Pelepasan formaldehyde kekal bawah had regulatory sepanjang tempoh rawatan.\n\nItulah standard yang patut dipakai untuk dakwaan ni: exposure data terukur berbanding baseline sebenar, bukan uji bau berdasarkan skandal lama. Kalau nak cabar dakwaan \"formaldehyde-free\", bawa exposure data, bukan ingatan tahun 2010.\n\nSources: Toxicology and Applied Pharmacology, Epub 9 July 2026 [SAHKAN: authors, volume/issue, DOI]\n\n#CosmeticScience #RegulatoryAffairs #KeratinTreatment #ExposureAssessment #HairCareChemistry"},"en":{"linkedin":"People keep treating \"formaldehyde-free keratin treatment\" as a slogan to be debunked, not a claim to be tested. The reflex is: glyoxylic acid still smells like the old Brazilian Blowout, so it must still release formaldehyde. That reflex skips the actual chemistry.\n\nGlyoxylic acid does not follow the same reaction pathway as methylene glycol/formaldehyde systems. A new measured-exposure study in Toxicology and Applied Pharmacology backs that up with real dermal exposure data, not assumptions.\n\nConsumer oxalic acid exposure from these products came in 20 to 41 times lower than typical daily dietary and endogenous oxalate intake (22 to 45 mg/day). For hairstylists doing repeated applications, exposure was over 860 times lower. Formaldehyde release stayed under regulatory limits for the full treatment duration.\n\nThat is the standard this claim should be held to: measured exposure against a real baseline, not a smell test against an old scandal. If you want to challenge a \"formaldehyde-free\" claim, bring exposure data, not a memory of 2010.\n\nSources: Toxicology and Applied Pharmacology, Epub 9 July 2026 [SAHKAN: authors, volume/issue, DOI]\n\n#CosmeticScience #RegulatoryAffairs #KeratinTreatment #ExposureAssessment #HairCareChemistry"}}'::jsonb, 'Toxicology and Applied Pharmacology, Epub 9 July 2026 [SAHKAN: authors, volume/issue, DOI]', '[]'::jsonb, '2026-09-29'::date, '06:00', 'draft', '[]'::jsonb, 0, '{}'::jsonb, null, null, '2026-09-25T06:50:34.267Z'::timestamptz) on conflict (id) do nothing;  -- d0izs7q7jo (draft)
insert into public.semasa_posts (id, idea_id, stream, domain, angle, lang, hook, text, citation, slides, date, slot, status, flags, hard_flags, published, posted_at, archived_at, created_at) values ('239180b4-3a83-5302-b705-11a8f386af39'::uuid, 'e5f06db5-89a4-5464-bca0-dd377f684e8f'::uuid, 'linkedin', null, 'D', 'en', 'There is no single ''benzophenone'' verdict. There is a family: benzophenone-1, -3, -4, -9, -11 and more, each with its own use pattern, concentration range and toxicology file.', '{"bm":{"linkedin":"Tak ada satu keputusan untuk ''benzophenone''. Ia satu kumpulan: benzophenone-1, -3, -4, -9, -11 dan lain-lain, setiap satu ada usage pattern, concentration range dan toxicology file sendiri.\n\nCosmetic Ingredient Review (CIR) Expert Panel menilai setiap derivatif secara berasingan. Oxybenzone, iaitu benzophenone-3, diharamkan di reef-protected zone seperti sebahagian Hawaii dan Palau atas sebab alam sekitar, kebimbangan coral bleaching, bukan sebab CIR kata ia tak selamat pada kulit.\n\nDua soalan berbeza, dijawab oleh dua badan berbeza, atas dua sebab berbeza. Satu ecotoxicology peringkat destinasi. Satu lagi dermal safety peringkat use-concentration.\n\nKalau anda formulate dengan derivatif benzophenone sebagai UV filter atau photostabilizer, cari CAS number spesifik anda dalam CIR assessment dan semak kesimpulan yang berkaitan dengan use category dan peratusan sebenar. Jangan pinjam headline larangan di pantai untuk buat keputusan pada ingredient sheet anda.\n\nHad ASEAN Cosmetic Directive Annex III untuk entri UV filter juga terpakai bila relevan.\n\nSources: CIR Expert Panel, Safety Assessment of Benzophenones as Used in Cosmetics. ASEAN Cosmetic Directive, Annex III"},"en":{"linkedin":"There is no single ''benzophenone'' verdict. There is a family: benzophenone-1, -3, -4, -9, -11 and more, each with its own use pattern, concentration range and toxicology file.\n\nThe Cosmetic Ingredient Review (CIR) Expert Panel evaluates them individually. Oxybenzone, which is benzophenone-3, got banned in reef-protected zones like parts of Hawaii and Palau for environmental reasons, coral bleaching concern, not because CIR flagged it unsafe on skin.\n\nTwo different questions, answered by two different bodies, for two different reasons. One is ecotoxicology at a destination level. The other is dermal safety at a use-concentration level.\n\nIf you formulate with a benzophenone derivative as a UV filter or photostabilizer, find your specific CAS number in the CIR assessment and check the conclusion tied to your actual use category and percentage. Do not borrow a beach-ban headline to make a call on your ingredient sheet.\n\nASEAN Cosmetic Directive Annex III limits for UV filter entries also apply where relevant."}}'::jsonb, 'CIR Expert Panel, Safety Assessment of Benzophenones; ASEAN Cosmetic Directive, Annex III', '[]'::jsonb, '2026-09-26'::date, '19:00', 'draft', '[]'::jsonb, 0, '{}'::jsonb, null, null, '2026-09-23T13:36:08.619Z'::timestamptz) on conflict (id) do nothing;  -- g2g41rc2o6 (draft)
insert into public.semasa_posts (id, idea_id, stream, domain, angle, lang, hook, text, citation, slides, date, slot, status, flags, hard_flags, published, posted_at, archived_at, created_at) values ('bae303e2-79b7-5563-9f13-d1a7d7a148f8'::uuid, '198a09e6-745c-5cea-a0ac-bfecd0f64d7a'::uuid, 'regulab', 'kosmetik', null, 'bm', 'Senarai pembatalan NPRA bukan berita. Ia dokumen kerja percuma yang kebanyakan peruncit tak pernah buka.', '{"bm":{"instagram":"Ramai peruncit kosmetik anggap senarai pembatalan notifikasi NPRA sebagai sesuatu yang mereka baca bila ia jadi viral. Sebenarnya ia dokumen kerja, dikemas kini sepanjang tahun, terbuka kepada sesiapa sahaja, dan percuma untuk disemak.\n\nSetakat semakan 19 Sept 2026, antara yang tersenarai: Saqa Glowing Turmeric Night Treatment Cream (merkuri), Glowing Night Treatment dan Glowing Herbal Treatment, Chomel Hand Sanitizer (methanol), Remy Laure Soothing Cream (hydroquinone).\n\nSebaik sahaja notifikasi dibatalkan, produk itu tak boleh diimport, dikilang, diedar atau dijual, tak kira berapa lama ia dah duduk atas rak anda. ''Saya tak tahu ia dah dibatalkan'' bukan pembelaan bila rekod itu public dan anda memang tak semak.\n\nKalau anda peruncit, dropshipper atau pemilik kedai kosmetik, semak senarai ni sebelum anda letak deposit untuk stok baharu. Bukan selepas pelanggan hantar mesej tanya kenapa produk yang anda jual ada dalam senarai tu.\n\nDue diligence bukan kerja NPRA sahaja. Bila produk itu atas rak anda, tanggungjawab semak jatuh pada anda juga.","facebook":"Senarai pembatalan notifikasi kosmetik NPRA bukan berita, ia dokumen kerja yang dikemas kini sepanjang tahun dan percuma untuk sesiapa semak.\n\nSetakat semakan 19 Sept 2026: Saqa Glowing Turmeric Night Treatment Cream (merkuri), Glowing Night Treatment, Glowing Herbal Treatment, Chomel Hand Sanitizer (methanol), Remy Laure Soothing Cream (hydroquinone), semua tersenarai.\n\nProduk yang notifikasinya dibatalkan tak boleh diimport, dikilang, diedar atau dijual. ''Saya tak tahu'' bukan pembelaan bila stok masih atas rak.\n\nPeruncit dan dropshipper: semak dulu sebelum ambil stok, bukan lepas pelanggan tanya.","threads":"Senarai pembatalan notifikasi kosmetik NPRA itu percuma dan terbuka untuk sesiapa. Ia bukan berita, ia due diligence.\n\nBila notifikasi dibatalkan (contoh terkini: produk bermerkuri, methanol, hydroquinone), produk itu tak boleh diimport, dikilang, diedar atau dijual.\n\n''Saya tak tahu'' tak jalan bila rekod tu public dan anda tak semak."},"en":{"instagram":"Most cosmetics retailers treat NPRA''s product notification cancellation list as something they only read about when it goes viral. It is actually a working document, updated all year, open to anyone, and free to check.\n\nAs of the 19 Sept 2026 review, listed products include Saqa Glowing Turmeric Night Treatment Cream (mercury), Glowing Night Treatment and Glowing Herbal Treatment, Chomel Hand Sanitizer (methanol), and Remy Laure Soothing Cream (hydroquinone).\n\nOnce a notification is cancelled, that product cannot be imported, manufactured, distributed or sold, no matter how long it has already been sitting on your shelf. ''I didn''t know it was cancelled'' is not a defence when the record is public and you simply didn''t check.\n\nIf you''re a retailer, dropshipper or cosmetics shop owner, check this list before you commit to new stock, not after a customer messages asking why the product they bought from you is on it.\n\nDue diligence isn''t NPRA''s job alone. If it''s on your shelf, checking it is on you too.","facebook":"NPRA''s cosmetic notification cancellation list isn''t news, it''s a working document updated all year and free for anyone to check.\n\nAs of the 19 Sept 2026 review: Saqa Glowing Turmeric Night Treatment Cream (mercury), Glowing Night Treatment, Glowing Herbal Treatment, Chomel Hand Sanitizer (methanol), and Remy Laure Soothing Cream (hydroquinone) are all listed.\n\nOnce cancelled, a product can''t be imported, manufactured, distributed or sold. ''I didn''t know'' isn''t a defence.\n\nRetailers and dropshippers: check before you stock, not after a customer asks.","threads":"NPRA''s cosmetics cancellation list is free and open to anyone. It''s not news, it''s due diligence.\n\nOnce a notification is cancelled (recent examples: mercury, methanol, hydroquinone products), that product can''t be imported, made, distributed or sold.\n\n''I didn''t know'' doesn''t hold up when the record is public and you never checked."}}'::jsonb, 'NPRA, Senarai Pembatalan Produk Kosmetik Bernotifikasi (laman rasmi NPRA), semakan 19 Sept 2026', '[]'::jsonb, '2026-09-28'::date, '13:00', 'draft', '[{"hard":true,"where":"Post","msg":"instagram needs an image"}]'::jsonb, 1, '{}'::jsonb, null, null, '2026-09-20T16:33:49.089Z'::timestamptz) on conflict (id) do nothing;  -- g4q4ebd0dr (draft)
insert into public.semasa_posts (id, idea_id, stream, domain, angle, lang, hook, text, citation, slides, date, slot, status, flags, hard_flags, published, posted_at, archived_at, created_at) values ('f8b8cd14-7acc-51cf-928c-2c6dcf1b2cbd'::uuid, '07639adb-127e-5497-be0f-b10a9813349a'::uuid, 'regulab', 'halal_my', null, 'bm', 'Premis bersijil halal boleh ambil pekerja bukan Islam. Ramai pengusaha tolak calon baik sebab silap faham ini.', '{"bm":{"instagram":"Lepas isu tular seorang pekerja bukan Islam diberhentikan di sebuah premis makanan di Bukit Bintang, ramai pengusaha mula panik dan anggap sijil halal maksudnya semua pekerja kena Muslim.\n\nItu silap.\n\nJAKIM sendiri dah jelaskan dalam laman Isu-Isu Tular Halal rasmi mereka: Manual Prosedur Pensijilan Halal Malaysia (Domestik) 2020 tidak menghalang pekerja bukan Islam bekerja di premis bersijil halal.\n\nYang diperlukan cuma tiga perkara, dan semuanya soal struktur, bukan agama seluruh barisan pekerja:\n\nSatu, sekurang-kurangnya seorang pekerja Muslim warganegara Malaysia, berjawatan tetap, bertugas sepanjang tempoh operasi atau setiap syif.\n\nDua, seorang penyelia Halal ditetapkan di premis tersebut.\n\nTiga, setiap pekerja (tak kira agama) hadir latihan kesedaran halal sekurang-kurangnya sekali setiap tiga tahun.\n\nRamai pengusaha yang saya jumpa dah terlajak tolak calon bagus sebab ingat pensijilan halal ni sekatan pengambilan. Sebenarnya ia sekadar syarat operasi: ada seorang Muslim tetap setiap syif, ada penyelia, dan latihan jalan macam biasa.\n\nSemak struktur syif anda dulu sebelum buat keputusan pengambilan.","facebook":"Ramai ingat sijil halal bermaksud semua pekerja kena Muslim. Silap.\n\nJAKIM dah jelaskan dalam laman Isu-Isu Tular Halal rasmi: Manual Prosedur Pensijilan Halal Malaysia (Domestik) 2020 tidak menghalang pekerja bukan Islam di premis bersijil halal.\n\nSyarat sebenar cuma tiga: seorang pekerja Muslim warganegara Malaysia bertugas setiap syif, seorang penyelia Halal di premis, dan setiap pekerja hadir latihan kesedaran halal sekali setiap tiga tahun.\n\nItu syarat struktur syif, bukan sekatan pengambilan pekerja.","threads":"Sijil halal tak larang pekerja bukan Islam. JAKIM dah sahkan dalam laman Isu-Isu Tular Halal rasmi mereka.\n\nSyarat sebenar: seorang Muslim tetap setiap syif, seorang penyelia Halal, dan latihan kesedaran sekali setiap tiga tahun.\n\nBukan seluruh barisan pekerja kena Muslim."},"en":{"instagram":"After the viral incident of a non-Muslim staff being let go at a Bukit Bintang food premise, plenty of owners panicked and assumed halal certification means every worker must be Muslim.\n\nThat''s wrong.\n\nJAKIM''s own Isu-Isu Tular Halal page states it plainly: the Manual Prosedur Pensijilan Halal Malaysia (Domestik) 2020 does not bar non-Muslim staff at halal-certified premises.\n\nThe actual requirement is three concrete things, all structural, not a blanket religious hiring rule:\n\nOne, at least one Malaysian Muslim staff, permanently employed, on duty throughout operating hours or every shift.\n\nTwo, a designated Halal supervisor at the premise.\n\nThree, every staff member (regardless of religion) attends halal awareness training at least once every three years.\n\nOwners keep rejecting good candidates over a rule that doesn''t exist as they imagine it. What''s actually required is one Muslim on shift and one supervisor, not a fully Muslim workforce.\n\nCheck your shift structure before you screen out a candidate.","facebook":"Plenty of owners think halal certification means every staff must be Muslim. It doesn''t.\n\nJAKIM''s official Isu-Isu Tular Halal page confirms it: the Manual Prosedur Pensijilan Halal Malaysia (Domestik) 2020 does not prohibit non-Muslim staff at halal-certified premises.\n\nThe real requirement: one Malaysian Muslim staff on duty every shift, one Halal supervisor at the premise, and every staff attending halal awareness training once every three years.\n\nThat''s a shift structure requirement, not a hiring ban.","threads":"Halal certification does not ban non-Muslim staff. JAKIM confirmed this on its official Isu-Isu Tular Halal page.\n\nThe real requirement: one Muslim staff per shift, one Halal supervisor, awareness training every three years.\n\nNot a fully Muslim workforce."}}'::jsonb, 'JAKIM, laman Isu-Isu Tular Halal (rasmi), merujuk Manual Prosedur Pensijilan Halal Malaysia (Domestik) 2020, dibaca 19 Sept 2026', '[]'::jsonb, '2026-10-06'::date, '08:00', 'draft', '[{"hard":true,"where":"Post","msg":"instagram needs an image"}]'::jsonb, 1, '{}'::jsonb, null, null, '2026-09-21T16:50:00.501Z'::timestamptz) on conflict (id) do nothing;  -- g8xbjqdola (draft)
insert into public.semasa_posts (id, idea_id, stream, domain, angle, lang, hook, text, citation, slides, date, slot, status, flags, hard_flags, published, posted_at, archived_at, created_at) values ('ee65d4f6-7758-5455-8570-17a650689b98'::uuid, '413a9cc9-c5b2-5943-aaca-144f676e9913'::uuid, 'linkedin', null, 'E', 'en', 'A slimming injection put a woman into anaphylactic shock from the drug meant to save her liver.', '{"bm":{"linkedin":"Liquid lipo bukan facial. Ia adalah deoxycholic acid, phosphatidylcholine dan L-carnitine yang disuntik ke dalam badan, dan satu case report dalam Annals of African Medicine, published online 24 September 2026, tunjukkan kenapa ini penting.\n\nSeorang wanita 31 tahun tanpa sejarah penyakit hati mengalami severe hepatocellular drug-induced liver injury selepas suntikan tersebut: ALT 2227 U/L, bilirubin 6.2 mg/dL. Doktor bagi IV N-acetylcysteine, antidote standard. Selepas itu dia pula alami anaphylactic reaction terhadap antidote tersebut.\n\nItu dua systemic pharmacological event daripada satu prosedur yang dipasarkan sebagai cosmetic, bukan satu.\n\nDi Malaysia, sebarang injectable yang bertindak dalam badan adalah drug atau medical device, bukan notified cosmetic product. Premis yang menjalankannya jatuh bawah Private Healthcare Facilities and Services Act 1998, bukan lesen salun kecantikan, dan injector perlu dilatih untuk kenal dan urus anaphylaxis serta drug-induced liver injury, bukan sekadar teknik suntikan.\n\nKalau klinik tawarkan liquid lipo bawah notifikasi cosmetic, file itu memang tak pernah dinilai untuk risiko ini. Keputusan classification itulah yang tentukan siapa yang layak dari segi undang-undang untuk uruskan komplikasi bila ia berlaku.\n\nSources: Case report, Annals of African Medicine, published online 24 Sept 2026 [SAHKAN: authors and DOI, not retrievable without direct journal database access]; Private Healthcare Facilities and Services Act 1998.\n\n#RegulatoryAffairs #Cosmetovigilance #NPRA #PatientSafety #AestheticMedicine"},"en":{"linkedin":"Liquid lipo is not a facial. It is deoxycholic acid, phosphatidylcholine and L-carnitine injected into the body, and a case report in Annals of African Medicine, published online 24 September 2026, shows exactly why that matters.\n\nA 31-year-old woman with no prior liver disease developed severe hepatocellular drug-induced liver injury after the injection: ALT 2227 U/L, bilirubin 6.2 mg/dL. Doctors gave IV N-acetylcysteine, the standard antidote. She then had an anaphylactic reaction to the antidote itself.\n\nThat is two systemic pharmacological events from one procedure marketed as cosmetic, not one.\n\nIn Malaysia, an injectable that acts inside the body is a drug or medical device, not a notified cosmetic product. The premise administering it falls under the Private Healthcare Facilities and Services Act 1998, not a beauty-salon licence, and the injector needs training to recognise and manage anaphylaxis and drug-induced liver injury, not just injection technique.\n\nIf a clinic offers liquid lipo under a cosmetic notification, that file was never assessed for this. The classification decision is what determines who is legally allowed to manage the complication when it happens.\n\nSources: Case report, Annals of African Medicine, published online 24 Sept 2026 [SAHKAN: authors and DOI, not retrievable without direct journal database access]; Private Healthcare Facilities and Services Act 1998.\n\n#RegulatoryAffairs #Cosmetovigilance #NPRA #PatientSafety #AestheticMedicine"}}'::jsonb, 'Case report, Annals of African Medicine, online 24 Sept 2026; Private Healthcare Facilities and Services Act 1998', '[]'::jsonb, '2026-09-30'::date, '06:00', 'draft', '[]'::jsonb, 0, '{}'::jsonb, null, null, '2026-09-25T13:27:13.580Z'::timestamptz) on conflict (id) do nothing;  -- geeun3wb7e (draft)
insert into public.semasa_posts (id, idea_id, stream, domain, angle, lang, hook, text, citation, slides, date, slot, status, flags, hard_flags, published, posted_at, archived_at, created_at) values ('4499fdd4-b652-52dd-a05d-ec42cadbb2d1'::uuid, 'a8a9c520-eca5-5897-8937-7c3a951cb3fa'::uuid, 'regulab', 'halal_my', null, 'bm', 'Video premis ''warga Arab jual menu tak halal'' yang tular itu sebenarnya berlaku di Eropah, bukan Malaysia.', '{"bm":{"instagram":"Video yang tular ni cerita pasal sebuah premis makanan milik warga Arab jual menu tak halal. Ramai terus assume ia berlaku di Malaysia, ada yang dah mula kaitkan dengan nama kedai tempatan yang serupa.\n\nBila disemak, kejadian sebenar berlaku di sebuah negara Eropah. Bukan Malaysia.\n\nIni corak yang selalu berulang bila sesuatu tular: fakta pertama yang hilang bukan kandungan dakwaan itu sendiri, tapi lokasi sebenar kejadian. Orang bereaksi pada apa yang nampak dalam video, bukan pada di mana ia sebenarnya berlaku.\n\nUntuk pengguna dan pengusaha F&B, sebelum kaitkan sebarang tangkapan skrin dengan premis tempatan, semak dulu sama ada kejadian itu berlaku di Malaysia langsung. Kalau anda travel dan nak pastikan makanan di luar negara itu halal, rujuk senarai Badan Pensijilan Halal Luar Negara yang diiktiraf JAKIM. Logo pada premis tak semestinya sah kalau badan pensijilan itu tak masuk dalam senarai tersebut.\n\nLokasi kejadian yang tentukan sama ada isu ini relevan pada anda langsung, atau langsung tak berkaitan.","facebook":"Video tular tentang premis makanan milik warga Arab jual menu tak halal itu sebenarnya berlaku di sebuah negara Eropah, bukan Malaysia.\n\nFakta pertama yang hilang bila sesuatu tular bukan kandungan dakwaan, tapi lokasi sebenar kejadian. Sebelum kaitkan tangkapan skrin dengan premis tempatan, semak dulu sama ada ia berlaku di Malaysia langsung.\n\nKalau anda travel, rujuk senarai Badan Pensijilan Halal Luar Negara yang diiktiraf JAKIM sebagai panduan, bukan logo di dinding premis.","threads":"Video ''premis warga Arab jual menu tak halal'' yang tular itu sebenarnya kejadian di Eropah, bukan Malaysia.\n\nFakta yang selalu hilang bila sesuatu tular: lokasi sebenar, bukan kandungan dakwaan. Semak dulu sama ada ia berlaku di Malaysia sebelum kaitkan dengan premis tempatan."},"en":{"instagram":"A video going around claims a food premise owned by Arab nationals is selling non-halal items. Plenty of people assumed it happened in Malaysia, some even started tagging local outlets that looked similar.\n\nOnce checked, the actual incident happened in a European country. Not Malaysia.\n\nThis is the pattern that keeps repeating when something goes viral: the first fact people lose is not the content of the claim, it''s the actual location. People react to what they see on screen, not to where it actually took place.\n\nFor consumers and F&B operators, before linking any screenshot to a local premise, check first whether the incident happened in Malaysia at all. If you''re travelling and want to check whether food overseas is halal, refer to the list of Foreign Halal Certification Bodies recognised by JAKIM. A logo on the wall isn''t automatically valid if that certification body isn''t on the list.\n\nThe location of the incident is what decides whether this is relevant to you at all, or not related to you in any way.","facebook":"A viral video about a food premise owned by Arab nationals selling non-halal items actually happened in a European country, not Malaysia.\n\nThe first fact that gets lost when something goes viral isn''t the content of the claim, it''s the actual location. Before linking a screenshot to a local premise, check whether it happened in Malaysia at all.\n\nIf you travel, refer to JAKIM''s list of recognised Foreign Halal Certification Bodies as your guide, not the logo on the wall.","threads":"The viral ''Arab-owned premise selling non-halal food'' video actually happened in Europe, not Malaysia.\n\nThe fact people lose first when something goes viral is the location, not the claim itself. Check if it even happened in Malaysia before you link it to a local premise."}}'::jsonb, '[SAHKAN: kenyataan rasmi JAKIM yang mengesahkan lokasi sebenar video ini -- belum jumpa rujukan bertulis rasmi; senarai Badan Pensijilan Halal Luar Negara yang diiktiraf JAKIM adalah rujukan sedia ada di portal rasmi JAKIM dan boleh disahkan terus di sana]', '[]'::jsonb, '2026-10-03'::date, '13:00', 'draft', '[{"hard":true,"where":"Post","msg":"instagram needs an image"}]'::jsonb, 1, '{}'::jsonb, null, null, '2026-09-25T06:48:50.410Z'::timestamptz) on conflict (id) do nothing;  -- geouh0nzfm (draft)
insert into public.semasa_posts (id, idea_id, stream, domain, angle, lang, hook, text, citation, slides, date, slot, status, flags, hard_flags, published, posted_at, archived_at, created_at) values ('83a655b9-7b63-5560-b174-81a99ab4fba9'::uuid, '5c048eed-91be-5139-9ca4-87049ae7d6b5'::uuid, 'regulab', 'makanan', null, 'bm', 'Produk bersijil halal pun boleh kena recall. Sijil halal bukan jaminan keselamatan makanan.', '{"bm":{"instagram":"Produk bersijil halal pun boleh kena recall. Ramai pengusaha (dan pengguna) anggap sijil halal itu semacam ''lesen keselamatan'' juga. Bukan.\n\nPortal Halal Malaysia pernah menyiarkan kenyataan media bertarikh 24/04/2025 berkaitan recall sebuah produk makanan halal yang disijilkan di Indonesia. Kita tak sebut nama produk atau pengeluar di sini sebab itu bukan poin utama. Poin dia: produk yang sah halal pun boleh gagal spesifikasi mikrobiologi atau salah label alergen, dan bila itu berlaku, recall jatuh di bawah rejim food safety, bukan rejim halal.\n\nSijil halal sahkan sumber bahan, proses dan kebersihan ikut syariah. Itu sahaja skopnya. Ia bukan kelulusan food safety, bukan kelulusan kualiti, dan tak melindungi anda daripada recall. Dua rejim, dua pihak berkuasa (JAKIM/JAIN untuk halal, KKM/BKKM untuk food safety), dua dokumen berasingan.\n\nUntuk pengimport: sijil halal pembekal anda tak boleh gantikan due diligence food safety anda sendiri. Semak COA, semak shelf life, semak batch punya sendiri. Sijil halal pembekal cuma jawab soalan syariah, bukan soalan mikrobiologi.","facebook":"Produk bersijil halal pun boleh kena recall. Portal Halal Malaysia ada kenyataan media (24/04/2025) tentang recall sebuah produk makanan halal disijilkan di Indonesia. Kita tak sebut nama, sebab poinnya bukan itu.\n\nSijil halal sahkan syariah: sumber bahan, proses, kebersihan. Bukan food safety, bukan kualiti, bukan perlindungan daripada recall. Dua rejim, dua pihak berkuasa berbeza.\n\nUntuk pengimport: sijil halal pembekal tak gantikan due diligence food safety anda sendiri.","threads":"Produk bersijil halal pun boleh kena recall. Sijil halal sahkan syariah je, bukan food safety. Portal Halal Malaysia ada kenyataan media 24/04/2025 pasal ni. Dua rejim berbeza, dua pihak berkuasa berbeza. Sijil pembekal tak gantikan due diligence food safety anda sendiri."},"en":{"instagram":"A halal-certified product can still get recalled. A lot of founders (and consumers) treat the halal cert like a food safety approval too. It is not.\n\nPortal Halal Malaysia carried a media statement dated 24/04/2025 about a recall involving a certified halal food product in Indonesia. We are not naming the product or manufacturer here, that is not the point. The point is: a product can be genuinely halal-certified and still fail microbiological spec or carry a mislabelled allergen, and when that happens the recall sits under the food safety regime, not the halal one.\n\nHalal certification confirms syariah compliance on sourcing, process and cleanliness. That is the entire scope. It is not a food safety approval, not a quality approval, and it does not protect you from recall. Two regimes, two different regulators (JAKIM/JAIN for halal, KKM/BKKM for food safety), two separate documents.\n\nFor importers: your supplier''s halal cert does not replace your own food safety due diligence. Check the COA, check shelf life, check batch records yourself. Your supplier''s halal cert only answers the syariah question, not the microbiology one.","facebook":"A halal-certified product can still get recalled. Portal Halal Malaysia has a media statement (24/04/2025) on a recall of a certified halal food product in Indonesia. We''re not naming it, that''s not the point.\n\nHalal cert confirms syariah compliance: sourcing, process, cleanliness. Not food safety, not quality, not recall protection. Two regimes, two different regulators.\n\nFor importers: your supplier''s halal cert does not replace your own food safety due diligence.","threads":"A halal-certified product can still get recalled. Halal cert only confirms syariah compliance, not food safety. Portal Halal Malaysia has a media statement from 24/04/2025 on this. Two regimes, two regulators. Your supplier''s cert doesn''t replace your own due diligence."}}'::jsonb, 'Portal Halal Malaysia (JAKIM), kenyataan media 24/04/2025, dibaca 19/09/2026', '[]'::jsonb, '2026-09-26'::date, '08:00', 'draft', '[{"hard":true,"where":"Post","msg":"instagram needs an image"}]'::jsonb, 1, '{}'::jsonb, null, null, '2026-09-20T16:22:56.260Z'::timestamptz) on conflict (id) do nothing;  -- gq44zaz0ok (draft)
insert into public.semasa_posts (id, idea_id, stream, domain, angle, lang, hook, text, citation, slides, date, slot, status, flags, hard_flags, published, posted_at, archived_at, created_at) values ('348e56ac-1255-51bc-9bd9-3a123fefaf36'::uuid, null, 'linkedin', null, 'E', 'en', 'Ninety thousand units recalled, and the formula was never the problem.', '{"bm":{"linkedin":"Health Canada tarik balik Schwarzkopf Professional Osis Grip Mousse (200ml, Henkel Consumer Brands Canada, dikilang di Hungary, 25 nombor lot terjejas, kira-kira 90,089 unit dijual November 2023 hingga Jun 2026), diumumkan 21 September 2026.\n\nSebab: bahaya kecederaan. Pembungkusan boleh bocor bila ditekan dan tin boleh pecah, berisiko cederakan pengguna atau rosakkan harta benda. Satu laporan insiden, tiada kecederaan disahkan setakat tarikh pengumuman.\n\nTiada satu bahan pun disebut dalam recall ini. Ini kegagalan kejuruteraan pembungkusan, bukan kimia formula. Tapi ia tetap berjalan di bawah Cosmetic Regulations dan Food and Drugs Act yang sama seperti recall bahan aktif, sebab integriti bekas memang sebahagian daripada apa yang dinotifikasikan.\n\nFail QA yang berhenti pada keselamatan formula dan tak sentuh ujian integriti bekas bertekanan ada jurang sebenar. Ujian kebocoran dan tekanan patut duduk atas checklist yang sama dengan ujian kestabilan dan mikrob, bukan dianggap kerja jabatan pembungkusan sahaja.\n\nSources: Health Canada, Consumer Product Recall, Schwarzkopf Professional Osis Grip Mousse, RA-82649, published 21 Sept 2026\n\n#RegulatoryAffairs #ProductSafety #Cosmetovigilance #PackagingCompliance"},"en":{"linkedin":"Health Canada recalled Schwarzkopf Professional Osis Grip Mousse (200ml, Henkel Consumer Brands Canada, manufactured in Hungary, 25 affected lot numbers, roughly 90,089 units sold November 2023 to June 2026), announced 21 September 2026.\n\nReason: injury hazard. The can can leak under pressure and rupture, risking injury or property damage. One incident reported, no injuries confirmed as of the announcement date.\n\nNo ingredient is named anywhere in this recall. This is a packaging engineering failure, not a formulation chemistry one. It still runs under the same Cosmetic Regulations and Food and Drugs Act as an active-ingredient recall, because container integrity is part of what was notified in the first place.\n\nA QA file that stops at formula safety and never touches pressurised-container integrity testing has a real gap. Leak and pressure testing belongs on the same checklist as stability and microbial testing, not treated as packaging''s problem alone.\n\nSources: Health Canada, Consumer Product Recall, Schwarzkopf Professional Osis Grip Mousse, RA-82649, published 21 Sept 2026\n\n#RegulatoryAffairs #ProductSafety #Cosmetovigilance #PackagingCompliance"}}'::jsonb, 'Health Canada, Consumer Product Recall, Schwarzkopf Professional Osis Grip Mousse, RA-82649, published 21 Sept 2026', '[]'::jsonb, '2026-10-01'::date, '19:00', 'draft', '[]'::jsonb, 0, '{}'::jsonb, null, null, '2026-09-25T14:05:00.000Z'::timestamptz) on conflict (id) do nothing;  -- irfxmbvdq4 (draft)
insert into public.semasa_posts (id, idea_id, stream, domain, angle, lang, hook, text, citation, slides, date, slot, status, flags, hard_flags, published, posted_at, archived_at, created_at) values ('ad9c392c-0fc7-54c4-8429-9884ce18f734'::uuid, 'f8816827-d4c4-5c28-987b-1c720c5bd4d4'::uuid, 'regulab', 'makanan', null, 'bm', 'Oreo ''mengandungi lemak babi'' tular lagi. JAKIM dah jawab. Tapi ramai masih tersasar poin sebenar.', '{"bm":{"instagram":"Dakwaan Oreo ada lemak dan susu babi kembali tular. Dalam halaman Isu-Isu Tular Halal rasmi JAKIM, sudah dijelaskan: produk itu dihasilkan oleh Mondelez Indonesia Manufacturing dan disijilkan halal oleh BPJPH (Badan Penyelenggara Jaminan Produk Halal), Kementerian Agama Republik Indonesia, iaitu salah satu badan pensijilan halal luar negara yang diiktiraf JAKIM.\n\nTapi bab ni yang selalu tersasar bila cakap pasal produk import: anda tak perlu sijil JAKIM untuk produk itu sah halal di Malaysia. Yang anda perlukan ialah sijil daripada badan pensijilan yang berada dalam senarai pengiktirafan JAKIM.\n\nDan tu bukan semakan sekali sahaja. Kerja due diligence anda sebagai pengimport atau peruncit ada dua lapis:\n\n1. Sijil produk itu sendiri sah dan masih dalam tempoh.\n2. Badan yang mengeluarkan sijil tu masih berstatus diiktiraf pada tarikh anda mengimport, bukan pada tarikh sijil dikeluarkan.\n\nStatus pengiktirafan boleh berubah. Kalau anda import produk luar negara dan letak label halal atas rak tanpa semak dua-dua lapis ni, risiko tu bukan pada jenama asal, risiko tu jatuh atas anda sebagai peruncit di Malaysia.","facebook":"Isu Oreo tular semula: dakwaan ada lemak babi. JAKIM dah jawab dalam halaman Isu-Isu Tular Halal rasminya, produk itu disijilkan halal oleh BPJPH di Indonesia, badan yang diiktiraf JAKIM.\n\nPoin sebenar untuk pengimport: produk import tak perlu sijil JAKIM, tapi perlu sijil daripada badan yang masih dalam senarai pengiktirafan JAKIM. Dua lapis semakan: sijil sah, dan badan tu masih diiktiraf pada tarikh import, bukan tarikh sijil dikeluarkan.","threads":"Oreo tular lagi pasal ''lemak babi''. JAKIM dah jawab: BPJPH Indonesia yang sijilkan, badan diiktiraf JAKIM.\n\nPoin yang ramai terlepas: produk import bukan perlu sijil JAKIM, tapi sijil dari badan dalam senarai diiktiraf. Dan semakan tu dua lapis, bukan satu."},"en":{"instagram":"The Oreo ''contains pork fat and lard'' claim is circulating again. JAKIM''s own Isu-Isu Tular Halal page addressed it directly: the product is manufactured by Mondelez Indonesia Manufacturing and certified halal by BPJPH (Badan Penyelenggara Jaminan Produk Halal) under Indonesia''s Ministry of Religious Affairs, one of the foreign halal certification bodies recognized by JAKIM.\n\nHere is the part importers and retailers keep missing: an imported product does not need a JAKIM certificate to be halal-valid in Malaysia. It needs a certificate from a body that sits on JAKIM''s recognition list.\n\nThat check has two layers, not one:\n\n1. The product certificate itself is valid and current.\n2. The issuing body is still on JAKIM''s recognized list as of the date you import, not the date the certificate was issued.\n\nRecognition status can change. If you''re bringing in foreign products and putting a halal label on the shelf without checking both layers, that risk sits with you as the Malaysian retailer, not the original brand.","facebook":"The Oreo pork fat claim is circulating again. JAKIM''s Isu-Isu Tular Halal page already addressed it: the product is certified by BPJPH Indonesia, a body recognized by JAKIM.\n\nThe real point for importers: you don''t need a JAKIM certificate on an imported product, you need one from a body still on JAKIM''s recognition list. That''s two checks, not one: the certificate is valid, and the body is still recognized on your import date.","threads":"Oreo pork claim again. JAKIM already answered: BPJPH Indonesia certified it, a body JAKIM recognizes.\n\nWhat importers miss: no JAKIM cert needed, just one from a recognized body. And that''s two checks, not one."}}'::jsonb, 'JAKIM, laman Isu-Isu Tular Halal (halal.gov.my), dibaca 19 Sept 2026', '[]'::jsonb, '2026-10-01'::date, '08:00', 'draft', '[{"hard":true,"where":"Post","msg":"instagram needs an image"}]'::jsonb, 1, '{}'::jsonb, null, null, '2026-09-21T16:25:39.843Z'::timestamptz) on conflict (id) do nothing;  -- jjidqvidk2 (draft)
insert into public.semasa_posts (id, idea_id, stream, domain, angle, lang, hook, text, citation, slides, date, slot, status, flags, hard_flags, published, posted_at, archived_at, created_at) values ('306c256a-53d4-55bb-9575-d9981172cabb'::uuid, '8315e399-01b8-52bd-a5a1-78e34d3b1423'::uuid, 'regulab', 'kosmetik', null, 'bm', '''Fragrance-free'' pada label tak bermakna tiada pewangi. Ia cuma bermakna tiada perkataan ''parfum'' ditulis.', '{"bm":{"instagram":"Ramai brand (dan pengguna) anggap ''fragrance-free'' atau ''bebas pewangi'' automatik selamat untuk kulit sensitif. Bukan macam tu cara ia berfungsi.\n\nKajian dalam jurnal Contact Dermatitis (Epub 21 Jun 2026) analisis 245 produk kosmetik dan pembersihan rumah di pasaran. Dakwaan ''fragrance-free/preservative-free'' pada label bercanggah dengan senarai ramuan sebenar dalam 21.2% produk yang diuji. Kosmetik pula ada bilangan dan beban ramuan pewangi jauh lebih tinggi berbanding produk pembersihan.\n\nAlergen pewangi paling kerap muncul: linalool, limonene, hexyl cinnamal. Pengawet: sodium benzoate, methylisothiazolinone. Semua ini boleh wujud dalam INCI list walaupun kotak depan tulis ''fragrance-free''.\n\nUntuk brand tempatan yang buat notifikasi NPRA: dakwaan ''fragrance-free'' kena disandarkan pada semakan silang INCI list produk siap, bukan sekadar tiada perkataan ''parfum'' atau ''fragrance'' pada senarai ramuan. Bahan pewangi individu seperti linalool atau limonene masih perlu diisytiharkan mengikut had pengisytiharan alergen di bawah ASEAN Cosmetic Directive Annex III, walaupun produk itu dilabel bebas pewangi.\n\nKalau QC team anda cuma check tiada word ''fragrance'' pada label, itu bukan due diligence. Itu andaian.\n\n[SAHKAN: had ambang % bagi setiap alergen dalam Annex III sebelum guna angka spesifik pada label anda]","facebook":"''Fragrance-free'' pada label tak semestinya bermakna tiada pewangi. Kajian dalam jurnal Contact Dermatitis (Epub 21 Jun 2026) yang analisis 245 produk pasaran jumpa dakwaan ini bercanggah dengan senarai ramuan sebenar dalam 21.2% kes.\n\nSebab utama: bahan pewangi individu macam linalool atau limonene boleh wujud dalam INCI list tanpa perkataan ''fragrance'' atau ''parfum'' tertulis. Bawah ASEAN Cosmetic Directive Annex III, bahan-bahan ini tetap kena diisytiharkan ikut had alergen, walaupun produk dilabel fragrance-free.\n\nKalau brand anda nak buat dakwaan ini, semak silang INCI list dulu. Jangan sandarkan pada tiada satu perkataan je.","threads":"''Fragrance-free'' pada label tak bermakna tiada pewangi. Ia cuma bermakna perkataan ''parfum'' tak ditulis.\n\nKajian 245 produk (Contact Dermatitis, Jun 2026): dakwaan ini bercanggah dengan INCI list sebenar dalam 21.2% kes. Linalool, limonene tetap boleh muncul dan kena diisytiharkan ikut Annex III."},"en":{"instagram":"A lot of brands (and consumers) assume ''fragrance-free'' automatically means safe for sensitive skin. That''s not how it works.\n\nA study in Contact Dermatitis (Epub 21 Jun 2026) analysed 245 cosmetic and household cleaning products on the market. The ''fragrance-free/preservative-free'' claim on the label contradicted the actual ingredient list in 21.2% of products tested. Cosmetics also had a much higher number and load of fragrance ingredients compared to cleaning products.\n\nMost common fragrance allergens found: linalool, limonene, hexyl cinnamal. Preservatives: sodium benzoate, methylisothiazolinone. All of these can sit in the INCI list even when the front of pack says ''fragrance-free''.\n\nFor local brands filing NPRA notifikasi: the ''fragrance-free'' claim needs to be backed by cross-checking the finished product''s actual INCI list, not just the absence of the word ''fragrance'' or ''parfum'' in the ingredient list. Individual fragrance substances like linalool or limonene still need to be declared per the allergen declaration thresholds under ASEAN Cosmetic Directive Annex III, even when the product is labelled fragrance-free.\n\nIf your QC team only checks that the word ''fragrance'' isn''t printed, that''s not due diligence. That''s an assumption.\n\n[SAHKAN: exact threshold percentages per allergen under Annex III before you put specific numbers on your own label]","facebook":"''Fragrance-free'' on a label doesn''t necessarily mean no fragrance. A study in Contact Dermatitis (Epub 21 Jun 2026) analysing 245 market products found this claim contradicted the actual ingredient list in 21.2% of cases.\n\nThe reason: individual fragrance substances like linalool or limonene can sit in the INCI list without the word ''fragrance'' or ''parfum'' ever being written. Under ASEAN Cosmetic Directive Annex III, these still need to be declared per allergen thresholds, even on a fragrance-free product.\n\nIf your brand wants to make this claim, cross-check the INCI list first. Don''t rely on the absence of one word.","threads":"''Fragrance-free'' doesn''t mean no fragrance. It just means the word ''parfum'' isn''t printed.\n\nStudy of 245 products (Contact Dermatitis, Jun 2026): the claim contradicted the actual INCI list in 21.2% of cases. Linalool, limonene can still show up and still need declaring under Annex III."}}'::jsonb, 'Contact Dermatitis journal, Epub 21 Jun 2026 (245-product market analysis); ASEAN Cosmetic Directive Annex III (allergen declaration thresholds)', '[]'::jsonb, '2026-10-02'::date, '21:00', 'draft', '[{"hard":true,"where":"Post","msg":"instagram needs an image"}]'::jsonb, 1, '{}'::jsonb, null, null, '2026-09-25T01:54:15.262Z'::timestamptz) on conflict (id) do nothing;  -- k1pju7557n (draft)
insert into public.semasa_posts (id, idea_id, stream, domain, angle, lang, hook, text, citation, slides, date, slot, status, flags, hard_flags, published, posted_at, archived_at, created_at) values ('a270f37a-23a8-5829-95e0-1d04d6d40ca4'::uuid, '3030567b-7e1d-5998-9668-e1adab7c83c1'::uuid, 'regulab', 'halal_my', null, 'bm', 'Ada sijil halal tak bermakna semua yang anda jual atau semua premis anda halal.', '{"bm":{"instagram":"Isu ini tular sejak beberapa hari lepas pasal status halal sebuah premis minuman herba. JAKIM sudah jelaskan: syarikat itu memang ada Sijil Pengesahan Halal Malaysia yang sah, tapi untuk skim produk makanan dan minuman, khusus untuk minuman herba bertin. Bukan untuk skim premis makanan.\n\nRamai usahawan silap faham benda ni. SPHM bukan satu sijil sepadu yang automatik cover segala-galanya di bawah nama syarikat anda. JAKIM keluarkan sijil ikut SKIM: rumah sembelihan, makanan, premis makanan, kosmetik, logistik, dan lain-lain. Setiap skim ada permohonan sendiri, penilaian sendiri, dan skop sendiri.\n\nSyarikat anda boleh ada SPHM sah untuk satu produk botol atau tin, tapi kalau seseorang semak sijil itu untuk premis atau produk lain yang tak pernah dipohon, ia akan nampak macam tak halal. Bukan sijil palsu, cuma skop tak sama.\n\nBila anda semak status halal syarikat lain (atau sendiri), jangan tanya ''ada sijil ke tak''. Tanya ''sijil ini cover skim apa, produk atau premis yang mana''. Semak terus kat portal MYeHALAL, bukan ikut apa yang dilekat kat botol atau signboard.\n\nUntuk pengusaha yang baru nak mohon: kalau anda ada lebih satu lini produk atau lebih satu premis, anda kena fikir dari awal sama ada perlu mohon lebih daripada satu skim. Ini bukan kos tambahan yang boleh dielak, ini keperluan asas skop sijil.","facebook":"Isu tular pasal status halal sebuah premis minuman herba. JAKIM sudah jelaskan: syarikat itu ada SPHM sah, tapi untuk skim minuman herba bertin sahaja, bukan skim premis makanan.\n\nRamai silap faham SPHM ni satu sijil sepadu yang cover semua bawah nama syarikat. Sebenarnya JAKIM keluarkan ikut SKIM (rumah sembelihan, makanan, premis, kosmetik, logistik) dan ikut produk atau premis yang dipohon khusus.\n\nAda SPHM untuk satu produk tak bermakna semua premis atau produk lain syarikat sama automatik halal. Semak skop, bukan sekadar ''ada sijil atau tak''.","threads":"JAKIM dah klarifikasi: sijil halal syarikat minuman herba itu sah, tapi untuk skim produk sahaja, bukan premis. SPHM bukan sijil sepadu. Ia ikut skim: makanan, premis, kosmetik, logistik, masing-masing dipohon berasingan. Ada sijil untuk satu produk tak sama dengan ada sijil untuk semua."},"en":{"instagram":"A halal status issue about an herbal drink premise has been going around. JAKIM has clarified: the company does hold a valid Malaysia Halal Certification, but under the food and beverage product scheme, specifically for canned herbal drinks. Not under the food premise scheme.\n\nThis mix-up is common. SPHM is not one blanket certificate covering everything under a company''s name. JAKIM issues certification by SCHEME: slaughterhouse, food, food premise, cosmetics, logistics, and others. Each scheme is a separate application with its own scope.\n\nA company can hold a valid SPHM for one bottled or canned product and still fail scrutiny if someone checks that certificate against a different premise or product that was never applied for. It is not a fake certificate. The scope simply does not extend that far.\n\nWhen checking halal status, whether your own or someone else''s, do not ask ''is there a certificate''. Ask ''which scheme, which product or premise does this certificate actually cover''. Check directly on MYeHALAL, not by what is printed on a bottle or signboard.\n\nIf you run more than one product line or more than one premise, you need to plan from the start whether you need to apply under more than one scheme. That is not an avoidable extra cost, it is basic scope requirement.","facebook":"A halal status issue about an herbal drink premise has circulated recently. JAKIM clarified: the company holds a valid SPHM, but under the beverage product scheme for canned herbal drinks, not the food premise scheme.\n\nSPHM is not a blanket certificate covering everything under a company name. JAKIM issues it by scheme, food, premise, cosmetics, logistics, each applied for separately.\n\nHolding a certificate for one product does not mean every premise or product under the same company is covered. Check the scope, not just whether a certificate exists.","threads":"JAKIM clarified: the herbal drink company''s halal cert is valid, but only for the product scheme, not the premise scheme. SPHM is not a blanket certificate. It runs by scheme, food, premise, cosmetics, logistics, each applied separately. One certified product does not mean everything is certified."}}'::jsonb, 'JAKIM, Skim Pensijilan Halal Malaysia (halal.gov.my), skop mengikut skim: rumah sembelihan, makanan, premis makanan, kosmetik, logistik', '[]'::jsonb, '2026-10-04'::date, '21:00', 'draft', '[{"hard":true,"where":"Post","msg":"instagram needs an image"}]'::jsonb, 1, '{}'::jsonb, null, null, '2026-09-21T16:44:18.587Z'::timestamptz) on conflict (id) do nothing;  -- kfnn7v6ctf (draft)
insert into public.semasa_posts (id, idea_id, stream, domain, angle, lang, hook, text, citation, slides, date, slot, status, flags, hard_flags, published, posted_at, archived_at, created_at) values ('dbf77ed8-32ca-5db2-a804-fb2bde6b65d9'::uuid, null, 'linkedin', null, 'A', 'en', 'Hexyl salicylate just moved from unrestricted to capped in UK cosmetics law, and the transition window is already running.', '{"bm":{"linkedin":"Hexyl salicylate baru sahaja beralih daripada tiada had kepada dihadkan dalam undang-undang kosmetik UK, dan tempoh peralihan itu dah pun berjalan.\n\nSI 2026/109, dibuat 4 Februari 2026, meminda retained Cosmetic Products Regulation (EC) No 1223/2009 UK. Bermula 15 Ogos 2026, hexyl salicylate duduk dalam Annex 3 dengan had kepekatan yang berbeza ikut jenis produk dan kumpulan umur, dari 0.001% sampai 2%. Stok yang dah dipasarkan di UK sebelum tarikh tu boleh kekal atas rak sampai 14 Februari 2027, lepas tu kena keluar.\n\nFasa kedua datang lebih lambat: bermula 23 Mac 2027, tiga belas bahan lagi berpindah ke Annex 2 sebagai bahan CMR yang dilarang, termasuk silver nanoparticles (1 hingga 100 nm) dan dinitrogen oxide. Produk yang dipasarkan sebelum tarikh tu dapat tempoh lebih panjang, sampai 22 September 2027.\n\nDua bahan berbeza, dua annex berbeza, dua jam berbeza. Formula yang dieksport ke UK kena semak kedua-dua tarikh terhadap senarai ramuan sendiri, bukan cuma tarikh yang masuk berita perdagangan.\n\nSources: The Cosmetic Products Regulation (EC) No 1223/2009 (Restriction of Chemical Substances) (Amendment and Transitional Provisions) (No. 2) Regulations 2026, SI 2026/109, legislation.gov.uk\n\n#RegulatoryAffairs #CosmeticRegulation #UKCosmetics #INCI #RAQA"},"en":{"linkedin":"Hexyl salicylate just moved from unrestricted to capped in UK cosmetics law, and the transition window is already running.\n\nSI 2026/109, made 4 February 2026, amends the UK''s retained Cosmetic Products Regulation (EC) No 1223/2009. From 15 August 2026, hexyl salicylate sits in Annex 3 with concentration limits that vary by product type and age group, from 0.001% up to 2%. Stock placed on the UK market before that date can stay on shelf until 14 February 2027, then it has to be gone.\n\nA second tranche lands later: from 23 March 2027, thirteen more substances move into Annex 2 as prohibited CMR entries, among them silver nanoparticles (1 to 100 nm) and dinitrogen oxide. Product placed before that date gets a longer runway, to 22 September 2027.\n\nTwo different substances, two different annexes, two different clocks. A formulation exported to the UK needs both dates checked against its own ingredient list, not just the one that made the trade press.\n\nSources: The Cosmetic Products Regulation (EC) No 1223/2009 (Restriction of Chemical Substances) (Amendment and Transitional Provisions) (No. 2) Regulations 2026, SI 2026/109, legislation.gov.uk\n\n#RegulatoryAffairs #CosmeticRegulation #UKCosmetics #INCI #RAQA"}}'::jsonb, 'The Cosmetic Products Regulation (EC) No 1223/2009 (Restriction of Chemical Substances) (Amendment and Transitional Provisions) (No. 2) Regulations 2026, SI 2026/109, made 4 February 2026, legislation.gov.uk', '[]'::jsonb, '2026-10-02'::date, '19:00', 'draft', '[{"hard":false,"where":"Caption (linkedin)","msg":"a link. Naming the instrument usually reads better than pasting a URL."}]'::jsonb, 0, '{}'::jsonb, null, null, '2026-09-26T13:46:15.000Z'::timestamptz) on conflict (id) do nothing;  -- l20261002b (draft)
insert into public.semasa_posts (id, idea_id, stream, domain, angle, lang, hook, text, citation, slides, date, slot, status, flags, hard_flags, published, posted_at, archived_at, created_at) values ('ddf05a83-322c-53ca-adc0-91c6dcb0bedc'::uuid, '1a752744-1b0b-5284-b7aa-92b6a930ecb2'::uuid, 'regulab', 'kosmetik', null, 'bm', 'Label kata ''AI-formulated''. NPRA tak ada laluan istimewa untuk formula macam ni.', '{"bm":{"instagram":"Ramai jenama sekarang letak ''AI-formulated'' atau ''direka guna kecerdasan buatan'' atas produk, seolah-olah itu jaminan keselamatan atau tiket lebih laju ke pasaran.\n\nUlasan sistematik dalam Current Pharmaceutical Design (14 Sept 2026) tinjau penggunaan AI dan machine learning dalam formulasi kosmetik: skrining bahan, ramalan toksisiti guna QSAR modelling, sampai reka bentuk produk peribadi, liputan literatur 2013 hingga Mac 2025. Kajian itu sendiri catat halangan yang masih belum selesai: regulatory harmonization antara pasaran dan algorithmic bias dalam data latihan.\n\nUntuk SME: cara formula anda dibuat, sama ada oleh chemist di makmal atau dioptimum guna model AI, tak ubah apa yang NPRA nak tengok. Produk tetap perlukan notifikasi yang sama, dokumentasi PIF yang sama, penilaian keselamatan yang sama.\n\nPerkataan ''AI'' pada label pemasaran itu claim marketing, bukan status regulatori. Safety assessor masih kena sign off macam biasa, tak kira apa alat yang syarikat guna untuk reka formula tu.","facebook":"Ramai jenama letak ''AI-formulated'' atas produk seolah-olah itu jaminan keselamatan atau laluan lebih pantas ke pasaran.\n\nUlasan sistematik dalam Current Pharmaceutical Design (14 Sept 2026) tinjau penggunaan AI/ML dalam formulasi kosmetik, sekali gus catat halangan yang belum selesai: regulatory harmonization dan algorithmic bias.\n\nUntuk SME: formula direka guna AI atau cara konvensional, produk tetap perlukan notifikasi NPRA yang sama, PIF yang sama, penilaian keselamatan yang sama. ''AI'' pada label bukan status regulatori.","threads":"Formula direka guna AI tak dapat laluan pintas kat NPRA. Ulasan sistematik (Current Pharmaceutical Design, 14 Sept 2026) tunjuk AI/ML dah masuk dalam skrining bahan dan ramalan toksisiti, tapi regulatory harmonization dan algorithmic bias masih halangan belum selesai. Notifikasi, PIF, safety assessment: semua sama macam formula konvensional. ''AI'' pada label itu marketing claim, bukan status regulatori."},"en":{"instagram":"More brands are slapping ''AI-formulated'' on their products like it is a safety guarantee or a shortcut to market.\n\nA systematic review in Current Pharmaceutical Design (14 Sept 2026) surveyed how AI and machine learning are used in cosmetic formulation: ingredient screening, toxicity prediction via QSAR modelling, personalised product design, covering literature from 2013 to March 2025. The same review flags what is still unresolved: regulatory harmonization across markets and algorithmic bias in training data.\n\nFor SMEs, this changes nothing on the compliance side. Whether your formula came from a chemist''s bench or an AI model, the product still needs the same NPRA notification, the same PIF documentation, the same safety assessment.\n\nThe word ''AI'' on a marketing label is a claim, not a regulatory status. The safety assessor still has to sign off exactly as before.","facebook":"Brands are marketing ''AI-formulated'' products like it is a safety guarantee or a faster route to market.\n\nA systematic review in Current Pharmaceutical Design (14 Sept 2026) covers AI/ML use in cosmetic formulation, and flags what remains unresolved: regulatory harmonization and algorithmic bias.\n\nFor SMEs: however the formula was designed, it still needs the same NPRA notification, same PIF, same safety assessment. ''AI'' on the label is not a regulatory status.","threads":"AI-formulated does not mean fast-tracked at NPRA. A systematic review (Current Pharmaceutical Design, 14 Sept 2026) shows AI/ML now used in ingredient screening and toxicity prediction, but regulatory harmonization and algorithmic bias are still unresolved. Notification, PIF, safety assessment: all the same as a conventional formula. ''AI'' on the label is a marketing claim, not a regulatory status."}}'::jsonb, 'Current Pharmaceutical Design, systematic review on AI/ML in cosmetic formulation (14 Sept 2026); notification/PIF/safety assessment requirement per Guidelines for Control of Cosmetic Products in Malaysia (2nd Ed, NPRA) [SAHKAN: exact seksyen for PIF and safety assessment obligation, since this draft cites the general requirement not the Seksyen 2.9/2.11 items already used]', '[]'::jsonb, '2026-10-02'::date, '08:00', 'draft', '[{"hard":true,"where":"Post","msg":"instagram needs an image"}]'::jsonb, 1, '{}'::jsonb, null, null, '2026-09-24T09:43:37.427Z'::timestamptz) on conflict (id) do nothing;  -- m0y389gwmi (draft)
insert into public.semasa_posts (id, idea_id, stream, domain, angle, lang, hook, text, citation, slides, date, slot, status, flags, hard_flags, published, posted_at, archived_at, created_at) values ('a4668f38-ec9d-5b57-b303-fa88139cc248'::uuid, 'a284326a-5707-5587-9684-daa5efc2ccc1'::uuid, 'regulab', 'halal_my', null, 'bm', '''Nasi Lemak'' atau ''Nasi Kandar'' atas papan tanda bukan jaminan halal, itu cuma nama masakan.', '{"bm":{"instagram":"Isu yang tular baru-baru ini pasal restoran jual Nasi Lemak Babi bersebelahan Nasi Kandar Babi buat ramai keliru. Ramai fikir nama pinggan tradisional macam ni automatik bawa maksud halal sebab makanan ni memang associated dengan masakan Melayu.\n\nTapi dari segi undang-undang, nama masakan dan pengisytiharan halal adalah dua benda berasingan. ''Nasi Lemak'' atau ''Nasi Kandar'' adalah nama resipi, bukan halal claim. Restoran boleh guna nama itu untuk versi apa-apa lauk sekalipun, termasuk daging babi, selagi mereka tak letak label atau iklan ''halal'' tanpa sijil sah dari JAKIM atau JAIN negeri.\n\nTrade Descriptions Act 2011 (Certification and Marking of Halal) Order yang kawal bila sesuatu premis boleh guna perkataan ''halal'' secara rasmi, bukan nama pinggan itu sendiri.\n\nUntuk pengusaha yang memang 100% halal pula, ini pengajaran penting: nama pinggan generik tak cukup untuk beritahu pelanggan Muslim premis anda berbeza. Papan tanda yang jelas dan sijil SPHM yang displayed di premise kekal cara paling pasti pelanggan boleh tahu beza anda dengan kedai sebelah yang guna nama sama tapi tak halal.\n\nJAKIM, “Penjelasan Isu Nasi Lemak Babi dan Nasi Kandar Babi” (Isu-Isu Tular Halal)","facebook":"Restoran jual Nasi Lemak Babi sebelah Nasi Kandar Babi buat ramai keliru minggu ni. Fakta: nama pinggan macam ''nasi lemak'' atau ''nasi kandar'' adalah nama masakan, bukan halal claim. Restoran boleh guna nama tu untuk versi babi pun, selagi tak dakwa halal tanpa sijil.\n\nUntuk premis yang memang halal, nama pinggan sahaja tak cukup. Papan tanda jelas dan sijil SPHM yang displayed kekal cara paling pasti pelanggan Muslim tahu beza premis anda.\n\nJAKIM, “Penjelasan Isu Nasi Lemak Babi dan Nasi Kandar Babi”","threads":"Nama pinggan macam ''nasi lemak'' bukan halal claim, itu nama masakan je. Restoran boleh jual versi babi guna nama sama, selagi tak dakwa halal tanpa sijil. Kalau anda halal betul, nama pinggan tak cukup, papan tanda dan sijil SPHM yang selesaikan keraguan pelanggan."},"en":{"instagram":"A restaurant selling Pork Nasi Lemak next to Pork Nasi Kandar has been the talk of the town lately, and it''s tripped a lot of people up. The assumption: dish names like these carry an implied halal status because they''re associated with Malay cuisine.\n\nLegally, that''s wrong. The dish name and the halal declaration are two separate things. ''Nasi Lemak'' or ''Nasi Kandar'' is a recipe name, not a halal claim. A restaurant can use that name for a pork version, a beef version, anything, as long as it does not advertise or label the premise as ''halal'' without a valid certificate from JAKIM or a state JAIN.\n\nThe Trade Descriptions (Certification and Marking of Halal) Order 2011, paragraph 4(1), governs when a business can officially use the word ''halal'', not the dish name itself.\n\nFor genuinely halal operators, the lesson cuts the other way: a generic dish name does not tell your Muslim customers anything. Clear signage and a displayed SPHM certificate remain the only reliable way customers can tell your premise apart from the one next door using the same dish name.\n\nJAKIM, “Penjelasan Isu Nasi Lemak Babi dan Nasi Kandar Babi” (Isu-Isu Tular Halal)","facebook":"A restaurant selling Pork Nasi Lemak next to Pork Nasi Kandar has people confused this week. The fact: dish names like ''nasi lemak'' or ''nasi kandar'' are recipe names, not halal claims. A restaurant can use those names for a pork version too, as long as it doesn''t claim halal without a certificate.\n\nFor genuinely halal premises, that''s the real lesson: the dish name alone tells customers nothing. Clear signage and a displayed SPHM certificate are what actually distinguish you.\n\nJAKIM, “Penjelasan Isu Nasi Lemak Babi dan Nasi Kandar Babi”","threads":"A dish name like ''nasi lemak'' isn''t a halal claim, it''s just a recipe name. A restaurant can sell a pork version under the same name, as long as it doesn''t claim halal without a certificate. If you''re genuinely halal, the dish name won''t do the work for you. Signage and a displayed SPHM certificate will."}}'::jsonb, 'Akta Perihal Dagangan 2011 [Akta 730], Perintah Perihal Dagangan (Perakuan dan Penandaan Halal) 2011, perenggan 4(1); JAKIM, Bahagian Pengurusan Halal, “Penjelasan Isu Nasi Lemak Babi dan Nasi Kandar Babi” (Isu-Isu Tular Halal)', '[]'::jsonb, '2026-09-29'::date, '13:00', 'draft', '[{"hard":true,"where":"Post","msg":"instagram needs an image"}]'::jsonb, 1, '{}'::jsonb, null, null, '2026-09-21T15:50:57.230Z'::timestamptz) on conflict (id) do nothing;  -- obggn29qlb (draft)
insert into public.semasa_posts (id, idea_id, stream, domain, angle, lang, hook, text, citation, slides, date, slot, status, flags, hard_flags, published, posted_at, archived_at, created_at) values ('4df8fffd-1ae1-5970-ad3a-98daf2463d67'::uuid, '8ddb19bd-268d-563d-81fe-9efc04012970'::uuid, 'linkedin', null, 'F', 'en', 'Antioxidant is not a safety category, and a new mouse study just showed exactly why that matters.', '{"bm":{"linkedin":"Satu preprint dari kumpulan University of Pennsylvania menguji topical sulforaphane, sebatian broccoli-sprout yang dipasarkan dalam skincare sebagai antioxidant pelindung, dalam mouse model keradangan seperti atopic dermatitis yang diinduksi dengan MC903.\n\nPada kulit normal, sulforaphane tidak buat apa-apa. Tapi pada kulit yang sudah inflamed, ia memburukkan dermatitis tersebut. Mekanismenya: IFN-gamma-producing CD8+ T cells yang direkrut dari periphery masuk ke kulit, menambah keradangan bukan menenangkannya.\n\nGaris ini kena jelas. Ini penemuan dalam mouse model, dalam preprint yang belum peer-reviewed. Ini bukan clinical evidence dan tidak menunjukkan sulforaphane memburukkan eczema pada manusia.\n\nTapi pengajaran untuk formulator tetap sama tak kira spesies. Kesan sesuatu barrier-active ingredient boleh bergantung sepenuhnya pada inflammatory state kulit yang menerimanya. Antioxidant itu describe chemical function, bukan safety outcome, dan soothing atau anti-inflammatory claim perlukan model atau population spesifik yang benar-benar diuji, bukan andaian class-level yang dipinjam dari reputasi ingredient tersebut.\n\nKalau dossier buat calming claim untuk reactive atau compromised skin, substantiation kena match dengan skin state itu, bukan healthy-skin panel.\n\nSources: [SAHKAN: tajuk preprint bioRxiv, penulis dan DOI untuk kajian University of Pennsylvania MC903/sulforaphane, posted 18 Sept 2026 - belum dijumpai melalui carian bioRxiv]\n\n#CosmeticScience #Sulforaphane #SkinBarrier #RegulatoryAffairs #Dermatology"},"en":{"linkedin":"A preprint out of a University of Pennsylvania lab tested topical sulforaphane, the broccoli-sprout compound sold in skincare as a protective antioxidant, in a mouse model of atopic-dermatitis-like inflammation induced with MC903.\n\nOn normal skin, sulforaphane did nothing. On already-inflamed skin, it made the dermatitis worse. The mechanism: IFN-gamma-producing CD8+ T cells recruited from the periphery into the skin, adding inflammation rather than calming it.\n\nDraw the line here clearly. This is a mouse model finding, in a preprint, not yet peer-reviewed. It is not clinical evidence and it does not show that sulforaphane worsens eczema in humans.\n\nBut the formulation lesson holds regardless of species. A barrier-active ingredient''s effect can depend entirely on the inflammatory state of the skin it meets. Antioxidant describes a chemical function, not a safety outcome, and a soothing or anti-inflammatory claim needs the specific model or population it was actually shown in, not a class-level assumption borrowed from the ingredient''s reputation.\n\nIf a dossier claims calming benefits for reactive or compromised skin, the substantiation has to match that skin state, not a healthy-skin panel.\n\nSources: [SAHKAN: bioRxiv preprint title, authors and DOI for the University of Pennsylvania MC903/sulforaphane study, posted 18 Sept 2026 - not yet located via bioRxiv search]\n\n#CosmeticScience #Sulforaphane #SkinBarrier #RegulatoryAffairs #Dermatology"}}'::jsonb, 'bioRxiv preprint, University of Pennsylvania group, posted 18 Sept 2026, not peer-reviewed - exact DOI and authors unverified', '[]'::jsonb, '2026-09-29'::date, '19:00', 'draft', '[]'::jsonb, 0, '{}'::jsonb, null, null, '2026-09-25T13:26:34.273Z'::timestamptz) on conflict (id) do nothing;  -- onuxvbvgtn (draft)
insert into public.semasa_posts (id, idea_id, stream, domain, angle, lang, hook, text, citation, slides, date, slot, status, flags, hard_flags, published, posted_at, archived_at, created_at) values ('4484ab97-001b-5556-8050-d5ec60a9581d'::uuid, '9ffd94f1-407f-53c4-b7a7-2d66e7aa1d95'::uuid, 'regulab', 'kajian_kes', null, 'bm', 'Dua produk, dua bahan berbeza, dibatalkan hujung Ogos 2026. Urutan kejadian sama tepat.', '{"bm":{"instagram":"Dua kes pembatalan notifikasi kosmetik berlaku hujung Ogos 2026: satu hand sanitizer sebab methanol melebihi had, satu soothing cream sebab hydroquinone. Bahan berbeza, kegunaan produk pun berbeza. Tapi urutan yang bawa kedua-dua produk ni ke senarai pembatalan NPRA sama je.\n\nNotifikasi diluluskan atas isytihar sendiri anda, bukan ujian makmal NPRA. Produk masuk pasaran. NPRA ambil sampel rawak atau terima aduan orang ramai. Makmal sahkan kandungan sebenar. Notifikasi dibatalkan, nama syarikat dan produk disenaraikan secara terbuka, dan kekal di situ.\n\nRamai founder anggap risiko datang lepas notifikasi diluluskan, jadi mereka relax bila dah dapat nombor notifikasi. Salah. Risiko wujud sejak hari pertama, sebab notifikasi itu self-declared, bukan pengesahan pihak ketiga bahawa formula anda selamat.\n\nTitik campur tangan anda ada di awal, bukan lepas produk masuk pasaran: ujian pengesahan bebas ke atas produk siap anda sendiri, bukan sekadar spec sheet dari pembekal. Buat sekurang-kurangnya sekali setiap formula, dan ulang setiap kali anda tukar pembekal bahan aktif, sebab kualiti bahan boleh berubah walaupun nama produk sama.\n\nKos ujian ni jauh lebih murah daripada kos recall stok. Dan nama anda tak masuk senarai awam NPRA yang sesiapa boleh cari bila-bila masa.","facebook":"Dua produk kosmetik dibatalkan notifikasinya hujung Ogos 2026, satu sebab methanol, satu sebab hydroquinone. Bahan berbeza, urutan kejadian sama: notifikasi lulus atas isytihar sendiri, produk masuk pasaran, NPRA sampel atau terima aduan, makmal sahkan, notifikasi dibatalkan dan nama disenaraikan terbuka.\n\nTitik campur tangan SME cuma satu, dan ia di awal: ujian pengesahan bebas ke atas produk siap, sekali setiap formula, ulang bila tukar pembekal bahan aktif. Lebih murah daripada recall, dan nama anda tak masuk senarai awam tu.","threads":"Dua produk kosmetik, dua bahan berbeza, dibatalkan notifikasi hujung Ogos 2026. Urutan sama: notifikasi lulus atas isytihar sendiri, bukan ujian NPRA. NPRA sampel lepas produk dah di pasaran, bukan sebelum. Titik campur tangan anda cuma satu: ujian pengesahan bebas produk siap, sebelum, bukan lepas."},"en":{"instagram":"Two cosmetic products had their NPRA notifications cancelled within days of each other, end of August 2026. One a hand sanitizer, methanol over the limit. One a soothing cream, hydroquinone. Different actives, different product category. Same exact sequence got them both onto the public cancellation list.\n\nThe notification gets approved based on your own self-declaration, not an NPRA lab test. The product goes to market. NPRA samples it from the shelf, or someone files a complaint. The lab confirms what is actually in it. The notification is cancelled, the company and product name go on a public list, and they stay there.\n\nMost founders assume the risk is behind them once the notification is approved. It is not. The risk starts on day one, because the notification is self-declared, not third party confirmation that your formula is safe.\n\nThe one point where you can actually intervene is early, before launch: independent verification testing on your own finished product, not just a supplier spec sheet. Do it at least once per formula, and again every time you change your active ingredient supplier, because material quality can shift even when the product name stays the same.\n\nThat test costs far less than a recall. And your name does not end up on a public NPRA list that anyone can find.","facebook":"Two cosmetic products, methanol in one, hydroquinone in the other, had their notifications cancelled within days of each other in late August 2026. Same sequence both times: self-declared notification approved, product hits shelves, NPRA samples or gets a complaint, lab confirms, notification cancelled, name listed publicly.\n\nThe only point an SME can intervene is early: independent verification testing on the finished product, once per formula, repeated when you switch active ingredient suppliers. Cheaper than a recall, and your name stays off that list.","threads":"Two cosmetic products, different actives, notifications cancelled days apart, late August 2026. Same sequence: self-declared notification, product on shelves, NPRA samples after, not before. The only intervention point is independent testing on the finished product, before launch, not after."}}'::jsonb, 'Senarai Pembatalan Produk Kosmetik Bernotifikasi, NPRA; Kenyataan Media KKM 21 Ogos 2026 (Chomel Hand Sanitizer, NOT221001118K) dan 24 Ogos 2026 (Remy Laure Soothing Cream)', '[]'::jsonb, '2026-09-30'::date, '21:00', 'draft', '[{"hard":true,"where":"Post","msg":"instagram needs an image"}]'::jsonb, 1, '{}'::jsonb, null, null, '2026-09-21T15:48:40.646Z'::timestamptz) on conflict (id) do nothing;  -- opcvqg6t7e (draft)
insert into public.semasa_posts (id, idea_id, stream, domain, angle, lang, hook, text, citation, slides, date, slot, status, flags, hard_flags, published, posted_at, archived_at, created_at) values ('26d92735-3fcc-5926-9406-5acf2da4252f'::uuid, '4d4789bf-c109-5c76-bb19-4dd92c52d50d'::uuid, 'regulab', 'halal_my', null, 'bm', 'Papan tanda halal, warna hijau kedai, nama Melayu, menu tanpa babi: bukan satu pun pengesahan status SPHM.', '{"bm":{"instagram":"Papan tanda \"halal\", warna hijau kedai, nama syarikat yang berbunyi Melayu, menu tanpa babi: bukan satu pun daripada itu adalah pengesahan status halal sesebuah premis.\n\nRamai confuse antara \"nampak halal\" dengan \"ada SPHM\" (Sijil Pengesahan Halal Malaysia). Dua benda berbeza. Premis boleh letak apa sahaja label sendiri kat depan kedai, tiada siapa halang. Yang sah cuma satu: adakah nama syarikat dan cawangan tu ada dalam senarai pemegang SPHM JAKIM.\n\nCara semak, ambil masa kurang satu minit:\n1. Pergi Portal Halal Malaysia atau sistem MYeHALAL\n2. Search guna nama syarikat berdaftar, bukan nama jenama pasaran\n3. Check status setiap cawangan, sebab satu syarikat boleh ada cawangan bersijil dan cawangan tak bersijil serentak\n4. Kalau tak jumpa, itu jawapannya: bukan pemegang SPHM\n\nJAKIM sendiri dah jelaskan berkali-kali bila isu tular pasal premis tertentu: premis berkenaan bukan pemegang SPHM dan JAKIM tak pernah keluarkan pensijilan untuk premis itu. Ini status dalam sistem, bukan pendapat orang ramai.\n\nKalau anda operator, jangan letak apa-apa simbol atau perkataan halal sebelum sijil tu betul-betul dalam tangan anda. Kalau anda consumer, semak dulu sebelum percaya papan tanda.","facebook":"Papan tanda \"halal\", warna hijau, nama Melayu, menu tanpa babi: bukan satu pun pengesahan status SPHM sesebuah premis.\n\nStatus sebenar cuma boleh disahkan melalui Portal Halal Malaysia atau sistem MYeHALAL, ikut nama syarikat dan cawangan, bukan nama jenama. Satu syarikat boleh ada cawangan bersijil dan cawangan tak bersijil serentak.\n\nBila isu tular, JAKIM selalunya beri jawapan sama: premis bukan pemegang SPHM, JAKIM tak pernah keluarkan pensijilan untuknya. Itu status sistem, bukan pendapat.","threads":"Papan tanda halal, warna kedai, nama Melayu, menu tanpa babi: bukan satu pun pengesahan status SPHM. Status sebenar cuma dalam Portal Halal Malaysia dan MYeHALAL, ikut nama syarikat dan cawangan. Satu syarikat boleh ada cawangan bersijil dan tak bersijil serentak. JAKIM dah jelaskan berkali-kali: bila viral, jawapannya sama, premis bukan pemegang SPHM."},"en":{"instagram":"A \"halal\" signboard, a green shopfront, a Malay-sounding name, a pork-free menu: none of that is proof of SPHM status.\n\nPeople keep confusing \"looks halal\" with \"holds SPHM\" (Sijil Pengesahan Halal Malaysia). A premise can put up whatever wording it wants on its own storefront, nobody stops that. The only thing that settles it is whether the exact registered company name and branch appears in JAKIM''s list of SPHM holders.\n\nChecking takes under a minute:\n1. Go to Portal Halal Malaysia or the MYeHALAL system\n2. Search by the registered company name, not the marketing brand name\n3. Check each branch separately, one company can have a certified outlet and an uncertified outlet at the same time\n4. If it doesn''t show up, that''s the answer, not a certificate holder\n\nJAKIM has said this repeatedly when a premise goes viral: not an SPHM holder, JAKIM never issued certification for it. That''s a system status, not an opinion.\n\nIf you run a premise, don''t put up any halal wording or symbol until the certificate is actually in your hand. If you''re a consumer, check before you trust the signboard.","facebook":"A \"halal\" signboard, a green shopfront, a Malay-sounding name, a pork-free menu: none of that is proof of SPHM status.\n\nThe only real check is Portal Halal Malaysia or the MYeHALAL system, searched by registered company name and branch, not brand name. One company can have a certified outlet and an uncertified outlet at the same time.\n\nWhen a premise goes viral, JAKIM''s answer is usually the same: not an SPHM holder, no certification ever issued for it. That''s a system status, not an opinion.","threads":"Halal signboard, green shopfront, Malay-sounding name, pork-free menu: none of it proves SPHM status. Only Portal Halal Malaysia and MYeHALAL settle it, searched by registered company name and branch. One company can have a certified branch and an uncertified branch at once. JAKIM keeps saying it: not a holder, never certified."}}'::jsonb, 'Portal Halal Malaysia (halal.gov.my) dan sistem MYeHALAL, JAKIM: kaedah rasmi semakan status pemegang SPHM mengikut nama syarikat dan cawangan.', '[]'::jsonb, '2026-09-29'::date, '21:00', 'draft', '[{"hard":true,"where":"Post","msg":"instagram needs an image"}]'::jsonb, 1, '{}'::jsonb, null, null, '2026-09-21T16:26:55.235Z'::timestamptz) on conflict (id) do nothing;  -- qefj57jzqb (draft)
insert into public.semasa_posts (id, idea_id, stream, domain, angle, lang, hook, text, citation, slides, date, slot, status, flags, hard_flags, published, posted_at, archived_at, created_at) values ('3ebe5918-cb0d-5ed5-a792-c3db84c863a8'::uuid, '3bcb040b-a68e-5ac4-9571-fd9c41918776'::uuid, 'linkedin', null, 'A', 'en', 'Two EU decisions just deferred biocide approval expiry dates. Cosmetics Annex status did not move.', '{"bm":{"linkedin":"Commission Implementing Decisions (EU) 2026/2124 dan (EU) 2026/2131 menangguhkan tarikh luput kelulusan dua active substance di bawah Biocidal Products Regulation, (EU) No 528/2012. Bahan yang terlibat ialah IPBC dan hydrogen peroxide.\n\nIni tempat orang keliru. IPBC turut disenaraikan dalam Annex V Cosmetics Regulation sebagai preservative yang dibenarkan, manakala hydrogen peroxide dalam Annex III sebagai restricted substance. Molekul sama, tapi dua regime undang-undang berbeza, dua dossier berbeza, dua logik competent authority berbeza.\n\nKedua-dua decision ini tidak menyentuh entry Annex kosmetik. Ia cuma extend tempoh approval biocidal product-type, isu supply chain dan product authorisation untuk disinfectant dan kegunaan preservative bukan-kosmetik. Bukan lampu hijau baru, bukan restriction baru untuk formulasi kosmetik anda.\n\nKalau produk anda cosmetic, rujukan compliance anda tetap Regulation (EC) No 1223/2009 dan syarat Annex-nya. Kalau anda juga letak biocidal product di pasaran, di situlah 2026/2124 dan 2026/2131 benar-benar memberi kesan.\n\n[SAHKAN: tarikh luput sebenar yang ditangguhkan dan product-type yang dilindungi di bawah Decisions 2026/2124 dan 2026/2131]\n\nSources: Commission Implementing Decision (EU) 2026/2124, OJ 24 September 2026; Commission Implementing Decision (EU) 2026/2131, OJ 24 September 2026; Regulation (EU) No 528/2012; Regulation (EC) No 1223/2009 Annex III dan Annex V.\n\n#RegulatoryAffairs #BiocidalProducts #CosmeticsRegulation #EUCompliance #IPBC"},"en":{"linkedin":"Commission Implementing Decisions (EU) 2026/2124 and (EU) 2026/2131 postpone the expiry of approval for two active substances under the Biocidal Products Regulation, (EU) No 528/2012. The substances are IPBC and hydrogen peroxide.\n\nHere is where people get confused. IPBC also sits in Annex V of the Cosmetics Regulation as an allowed preservative, and hydrogen peroxide sits in Annex III as a restricted substance. Same molecules, two different legal regimes, two different dossiers, two different competent authorities'' logic.\n\nThese decisions do not touch the cosmetics Annex entries. They extend the clock on the biocidal product-type approvals, which is a supply chain and product-authorisation issue for disinfectants and preservative use in non-cosmetic contexts, not a green light or a fresh restriction for your cosmetic formulation.\n\nIf your product is a cosmetic, your compliance reference stays Regulation (EC) No 1223/2009 and its Annex conditions. If you also place a biocidal product on the market, that is where 2026/2124 and 2026/2131 actually bite.\n\n[SAHKAN: exact deferred expiry dates and product-types covered under Decisions 2026/2124 and 2026/2131]\n\nSources: Commission Implementing Decision (EU) 2026/2124, OJ 24 September 2026; Commission Implementing Decision (EU) 2026/2131, OJ 24 September 2026; Regulation (EU) No 528/2012; Regulation (EC) No 1223/2009 Annex III and Annex V.\n\n#RegulatoryAffairs #BiocidalProducts #CosmeticsRegulation #EUCompliance #IPBC"}}'::jsonb, 'Commission Implementing Decisions (EU) 2026/2124 and (EU) 2026/2131, OJ 24 September 2026, under Regulation (EU) No 528/2012', '[]'::jsonb, '2026-10-03'::date, '19:00', 'draft', '[]'::jsonb, 0, '{}'::jsonb, null, null, '2026-09-26T18:51:32.214Z'::timestamptz) on conflict (id) do nothing;  -- qjc891x86v (draft)
insert into public.semasa_posts (id, idea_id, stream, domain, angle, lang, hook, text, citation, slides, date, slot, status, flags, hard_flags, published, posted_at, archived_at, created_at) values ('1651a696-056d-5e5b-8a3d-667dfdd25f35'::uuid, '36ceb6d0-85d8-5348-a5fa-c7dbab6ee11e'::uuid, 'regulab', 'farmaseutikal', null, 'bm', 'Kalau produk herba itu betul-betul berkesan dalam tiga hari, tanya bahan apa yang dicampur.', '{"bm":{"instagram":"Kalau produk herba itu betul-betul berkesan dalam tiga hari, tanya bahan apa yang dicampur.\n\nSenarai produk semula jadi dan tradisional yang dibatalkan pendaftaran NPRA tunjukkan corak yang sangat konsisten. Produk ''tenaga batin'' yang dibatalkan selalunya mengandungi sildenafil atau tadalafil. Produk ''kencing manis'' mengandungi glibenclamide. Produk sakit sendi mengandungi methyl salicylate dan thymol dalam kuantiti tak diisytiharkan. Plaster ubat mengandungi diphenhydramine. PS 21 Capsule (MAL15120007TC) dibatalkan kerana simvastatin.\n\nPerhatikan corak ini: setiap bahan yang dicampur adalah ubat farmaseutikal yang tepat sepadan dengan dakwaan produk itu. Ini bukan pencemaran tidak sengaja semasa proses pengeluaran. Ini reka bentuk formulasi supaya pengguna rasa kesan cepat, tanpa tahu apa yang mereka telan.\n\nUntuk pengusaha yang jual produk herba sebenar tanpa campuran ini, inilah sebab pelanggan anda skeptikal walaupun produk anda bersih. Dan inilah sebab nombor MAL anda bermakna: ia boleh disemak di laman NPRA, dan produk yang dibatalkan keluar dari senarai berdaftar.","facebook":"Kalau produk herba berkesan dalam tiga hari, tanya bahan apa yang dicampur.\n\nSenarai pembatalan NPRA untuk produk semula jadi dan tradisional tunjukkan corak konsisten: produk ''tenaga batin'' mengandungi sildenafil/tadalafil, produk kencing manis mengandungi glibenclamide, produk sakit sendi mengandungi methyl salicylate dan thymol, plaster ubat mengandungi diphenhydramine. Setiap bahan sepadan tepat dengan dakwaan produk. Ini reka bentuk, bukan kesilapan.\n\nNombor MAL anda bermakna sebab ia boleh disemak, dan produk dibatalkan hilang dari senarai.","threads":"Kalau produk herba kesan dalam tiga hari, tanya bahan apa dicampur.\n\nSenarai pembatalan NPRA: produk tenaga batin ada sildenafil, kencing manis ada glibenclamide, sakit sendi ada methyl salicylate, plaster ubat ada diphenhydramine. Setiap bahan sepadan tepat dengan dakwaan. Ini reka bentuk, bukan kesilapan.\n\nNombor MAL anda boleh disemak. Produk dibatalkan keluar dari senarai."},"en":{"instagram":"If an herbal product actually works in three days, ask what''s been mixed in.\n\nNPRA''s list of cancelled natural and traditional product registrations shows a very consistent pattern. Cancelled ''stamina'' products usually contain sildenafil or tadalafil. Cancelled ''diabetes'' products contain glibenclamide. Joint pain products contain undeclared quantities of methyl salicylate and thymol. Medicated plasters contain diphenhydramine. PS 21 Capsule (MAL15120007TC) was cancelled for simvastatin.\n\nNotice the pattern: every adulterant is a pharmaceutical that matches the product''s claim exactly. This isn''t accidental contamination during manufacturing. It''s formulation by design, so users feel fast results without knowing what they''ve swallowed.\n\nFor SMEs selling genuine herbal products without this, this is why your customers are skeptical even when your product is clean. And this is why your MAL number matters: it''s checkable on NPRA''s site, and cancelled products drop off that list.","facebook":"If an herbal product works in three days, ask what''s mixed in.\n\nNPRA''s cancelled product list for natural and traditional products shows a consistent pattern: ''stamina'' products with sildenafil/tadalafil, diabetes products with glibenclamide, joint pain products with methyl salicylate and thymol, medicated plasters with diphenhydramine. Every adulterant matches the claim exactly. That''s design, not error.\n\nYour MAL number matters because it''s checkable, and cancelled products drop off the list.","threads":"If an herbal product works in three days, ask what''s mixed in.\n\nNPRA cancelled list: stamina products with sildenafil, diabetes with glibenclamide, joint pain with methyl salicylate, medicated plasters with diphenhydramine. Every ingredient matches the claim exactly. Design, not error.\n\nYour MAL number is checkable. Cancelled products drop off the list."}}'::jsonb, 'NPRA, Pembatalan Pendaftaran Produk Komplementari dan Alternatif Atas Isu Campurpalsu — PS 21 Capsule, MAL15120007TC, simvastatin, dibatalkan PBKD mesyuarat ke-358, Kenyataan Akhbar KKM 5 Jun 2021', '[]'::jsonb, '2026-10-01'::date, '13:00', 'draft', '[{"hard":true,"where":"Post","msg":"instagram needs an image"}]'::jsonb, 1, '{}'::jsonb, null, null, '2026-09-21T16:45:54.440Z'::timestamptz) on conflict (id) do nothing;  -- r1u6lb8erj (draft)
insert into public.semasa_posts (id, idea_id, stream, domain, angle, lang, hook, text, citation, slides, date, slot, status, flags, hard_flags, published, posted_at, archived_at, created_at) values ('9cf6db78-966d-5595-b5d2-f4edda23dbd2'::uuid, '782f66e2-c913-5c0d-9d92-ebad531ccad2'::uuid, 'linkedin', null, 'G', 'en', 'Razor bump serums keep selling one fix for a problem that has three separate causes.', '{"bm":{"linkedin":"Pseudofolliculitis barbae bukan satu masalah sahaja. Ia melibatkan curved hair yang re-enter kulit, shave technique yang tinggalkan hair tip tajam, dan kadang-kadang hair-removal method yang memang tak sesuai untuk curly hair sejak awal.\n\nSatu expert consensus baru dalam JAMA Dermatology map best practice merentasi ketiga-tiga faktor ini: shave technique, pemilihan hair-removal method, dan topical atau procedural treatment. Bukan satu serum single-ingredient.\n\nIni masalah yang saya nampak dalam claims deck. Satu brand claim produk mereka \"treat\" razor bumps, senaraikan soothing extract sahaja. Soothing hanya address inflammation selepas ia berlaku. Ia tak buat apa-apa untuk follicle direction, dan tak buat apa-apa untuk hair growth cycle yang terus hasilkan curved hair yang sama.\n\nKalau anda formulate atau review claims dalam kategori ini, tanya mechanism mana yang actives anda betul-betul address: exfoliation untuk clear follicle opening, hair-removal approach yang ubah re-entry angle, atau sesuatu yang slow regrowth. Pilih satu dan nyatakan. Produk yang name mechanism dia defensible. Produk yang cuma cakap \"calms bumps\" adalah claim yang tunggu untuk dicabar.\n\nSources:\nAlomary SA, Baker NJ, Ugwueke G, et al. Expert Consensus Delphi Study on Management of Pseudofolliculitis Barbae. JAMA Dermatology, 23 Sept 2026.\n\n#dermatology #cosmeticscience #claimssubstantiation #RAQA #skinbarrier"},"en":{"linkedin":"Pseudofolliculitis barbae isn''t one problem. It''s curved hair re-entering the skin, shave technique that leaves a sharp hair tip, and sometimes a hair-removal method that was never suited to curly hair in the first place.\n\nA new expert consensus in JAMA Dermatology maps best practice across all three: shave technique, choice of hair-removal method, and topical or procedural treatment. Not a single-ingredient serum.\n\nHere''s the problem I see in claims decks. A brand says their product \"treats\" razor bumps and lists a soothing extract. Soothing addresses inflammation after the fact. It does nothing for follicle direction, and nothing for the hair growth cycle that keeps producing the same curved hair.\n\nIf you''re formulating or reviewing claims in this space, ask which mechanism your actives actually hit: exfoliation to clear the follicle opening, a hair-removal approach that changes re-entry angle, or something that slows regrowth. Pick one and say so. A product that names its mechanism is defensible. A product that just says \"calms bumps\" is a claim waiting to be challenged.\n\nSources:\nAlomary SA, Baker NJ, Ugwueke G, et al. Expert Consensus Delphi Study on Management of Pseudofolliculitis Barbae. JAMA Dermatology, 23 Sept 2026.\n\n#dermatology #cosmeticscience #claimssubstantiation #RAQA #skinbarrier"}}'::jsonb, 'JAMA Dermatology, Expert Consensus Delphi Study, Alomary SA, Baker NJ, Ugwueke G et al., 23 Sept 2026', '[]'::jsonb, '2026-09-28'::date, '06:00', 'draft', '[]'::jsonb, 0, '{}'::jsonb, null, null, '2026-09-25T03:46:24.948Z'::timestamptz) on conflict (id) do nothing;  -- wgugqu5dvk (draft)
insert into public.semasa_posts (id, idea_id, stream, domain, angle, lang, hook, text, citation, slides, date, slot, status, flags, hard_flags, published, posted_at, archived_at, created_at) values ('29c250b4-937f-5dcf-9ab1-4cd539feefad'::uuid, '3216f5aa-b96e-5cba-9219-7f6e2be3067c'::uuid, 'regulab', 'halal_my', null, 'bm', 'Sijil pembekal anda belum luput. Tapi itu bukan jaminan sijil itu masih sah.', '{"bm":{"instagram":"Ramai founder anggap kerja siasat pembekal habis sebaik sijil halal disemak semasa onboarding. Bukan begitu caranya.\n\nJAKIM boleh menarik balik pengiktirafan sesebuah badan pensijilan halal luar negara pada bila-bila masa. Bila itu berlaku, sijil yang badan tersebut keluarkan tidak lagi boleh menyokong status halal produk siap anda, walaupun sijil di tangan anda masih belum luput tarikhnya.\n\nIni isu yang jarang dibincangkan sebab ia tidak viral. Tapi untuk pengimport bahan mentah, kesannya paling mahal: seluruh batch boleh kehilangan asas halal tanpa anda sedar, sebab yang anda semak ialah sijil, bukan status pengiktirafan badan yang keluarkan sijil itu.\n\nYang perlu ada dalam sistem jaminan halal anda: satu senarai semak yang menyemak status pengiktirafan setiap badan pensijilan pembekal anda, sekurang-kurangnya setiap suku tahun. Bukan sekali sahaja semasa daftar pembekal baharu.\n\nSumber rasmi untuk semakan itu ialah senarai Foreign Halal Certification Body di portal Halal Malaysia (halal.gov.my). Senarai itu yang mengikat status halal anda, bukan sijil fizikal yang tersimpan dalam fail.","facebook":"Sijil halal pembekal masih belum luput tarikh tak bermakna ia masih sah digunakan.\n\nJAKIM boleh menarik pengiktirafan sesebuah badan pensijilan halal luar negara bila-bila masa. Bila itu berlaku, produk siap anda hilang asas halal walaupun sijil di tangan masih valid.\n\nMasukkan dalam sistem jaminan halal anda: semakan status pengiktirafan badan pensijilan setiap pembekal, sekurang-kurangnya setiap suku tahun, rujuk senarai Foreign Halal Certification Body di halal.gov.my. Senarai itu yang mengikat, bukan sijil dalam fail.","threads":"Sijil pembekal belum luput bukan bermakna ia masih sah. JAKIM boleh tarik pengiktirafan badan pensijilan luar negara bila-bila masa, dan bila itu berlaku produk siap anda hilang asas halal serta merta. Semak status badan pensijilan pembekal anda di senarai Foreign Halal Certification Body, halal.gov.my, setiap suku tahun. Bukan sekali masa onboarding."},"en":{"instagram":"Most founders think supplier due diligence ends once the halal certificate is checked during onboarding. That is not how it works.\n\nJAKIM can withdraw recognition from a foreign halal certification body at any time. When that happens, certificates issued by that body can no longer support your finished product''s halal status, even if the certificate you are holding has not expired.\n\nThis never trends online, but for importers of raw materials it is the most expensive thing to miss: an entire batch can lose its halal basis without you knowing, because what you checked was the certificate, not the recognition status of the body that issued it.\n\nWhat needs to be in your halal assurance system: a checklist that verifies the recognition status of every supplier''s certification body, at minimum every quarter, not just once at supplier registration.\n\nThe official reference for that check is the Foreign Halal Certification Body section on the Halal Malaysia portal (halal.gov.my). That list governs your halal status, not the paper sitting in your file.","facebook":"An unexpired certificate from your supplier does not mean it is still valid.\n\nJAKIM can withdraw recognition from a foreign halal certification body at any time. When that happens, your finished product loses its halal basis even if the physical certificate is not expired.\n\nBuild this into your halal assurance system: check the recognition status of each supplier''s certification body at least every quarter, against the Foreign Halal Certification Body list on halal.gov.my. That list is what binds you, not the certificate in your file.","threads":"An unexpired supplier certificate does not mean it is still valid. JAKIM can withdraw recognition from a foreign halal certification body anytime, and your finished product loses its halal basis the moment that happens. Check your suppliers'' certification bodies against the Foreign Halal Certification Body list on halal.gov.my every quarter, not just once at onboarding."}}'::jsonb, 'JAKIM, Bahagian Pengurusan Halal, Portal Halal Malaysia, “Withdrawal of Recognition of Foreign Halal Certification Bodies in France, Croatia, and China” — ARGML, CHQC dan CIA, berkuat kuasa 19 Februari 2025, tempoh peralihan hingga 19 Ogos 2025', '[]'::jsonb, '2026-09-29'::date, '08:00', 'draft', '[{"hard":false,"where":"Caption (instagram)","msg":"a link. Naming the instrument usually reads better than pasting a URL."},{"hard":false,"where":"Caption (facebook)","msg":"a link. Naming the instrument usually reads better than pasting a URL."},{"hard":false,"where":"Caption (threads)","msg":"a link. Naming the instrument usually reads better than pasting a URL."},{"hard":true,"where":"Post","msg":"instagram needs an image"}]'::jsonb, 1, '{}'::jsonb, null, null, '2026-09-20T16:31:03.893Z'::timestamptz) on conflict (id) do nothing;  -- xxnit29gwg (draft)
insert into public.semasa_posts (id, idea_id, stream, domain, angle, lang, hook, text, citation, slides, date, slot, status, flags, hard_flags, published, posted_at, archived_at, created_at) values ('bf3c27e0-53a1-5776-819a-b3ad4dadec63'::uuid, '98171666-d6d0-5502-8a38-63c7d4be1be1'::uuid, 'regulab', 'kosmetik', null, 'bm', 'Remy Laure Soothing Cream: notifikasi kena batal 24 Ogos 2026 sebab hydroquinone.', '{"bm":{"instagram":"Notifikasi NPRA keluar, ramai ingat produk dah ''lulus''. Tak.\n\nRemy Laure Soothing Cream kena batal notifikasi pada 24 Ogos 2026 sebab hydroquinone dikesan dalam formula. Hydroquinone bahan ubat, dilarang dalam kosmetik.\n\nNombor notifikasi keluar based on apa syarikat isytiharkan sendiri masa hantar permohonan. NPRA tak uji kandungan dulu.\n\nUjian sebenar jalan lepas produk di pasaran, melalui sampling dan aduan. Kalau kandungan tak match isytihar, atau ada bahan larangan, notifikasi boleh dibatalkan bila-bila, walau dah aktif bertahun.\n\nJadi bila produk ditarik, ''NPRA dah luluskan'' tak boleh pakai. Notifikasi bukan pengesahan kandungan. Tanggungjawab formula 100% pada syarikat yang notify.","facebook":"Remy Laure Soothing Cream kena batal notifikasi NPRA pada 24 Ogos 2026 sebab ada hydroquinone, bahan ubat yang dilarang dalam kosmetik.\n\nNotifikasi bukan lulus. Nombor keluar based on isytihar syarikat sendiri, bukan ujian NPRA. Ujian sebenar jalan lepas produk di pasaran.\n\nBila kena batal, tak boleh cakap ''NPRA dah luluskan''. Kandungan tak pernah disahkan sejak awal.","threads":"Notifikasi NPRA bukan lulus. Remy Laure Soothing Cream kena batal 24 Ogos 2026 sebab hydroquinone. Nombor keluar based on isytihar syarikat sendiri, NPRA tak uji dulu. Bila kena tarik, jangan cakap ''dah lulus''."},"en":{"instagram":"An NPRA notification number does not mean the product passed testing.\n\nRemy Laure Soothing Cream had its notification cancelled 24 August 2026 after hydroquinone turned up in the formula. A drug ingredient, banned in cosmetics.\n\nThe number is issued on what the company declares at submission. NPRA does not test upfront.\n\nReal testing happens post-market, through sampling and complaints. If content does not match the declaration, or a banned substance shows up, the notification can be cancelled anytime, even years later.\n\nSo when a product gets pulled, ''but NPRA approved it'' does not hold. That responsibility sits with the company that notified it.","facebook":"Remy Laure Soothing Cream had its NPRA notification cancelled 24 August 2026 after hydroquinone, a drug ingredient banned in cosmetics, was found in the formula.\n\nNotification is not approval. The number is issued on self-declaration, NPRA never tests it upfront. Real testing happens after the product is already on the market.\n\nWhen it gets cancelled, ''NPRA approved it'' does not hold. Nobody verified the content in the first place.","threads":"NPRA notification is not approval. Remy Laure Soothing Cream was cancelled 24 Aug 2026 over hydroquinone. The number rests on self-declaration, testing happens post-market. When a product gets pulled, ''it was approved'' does not hold."}}'::jsonb, '', '[{"title":"Notifikasi NPRA keluar, ramai anggap produk dah ''lulus''.","points":["Bukan begitu."]},{"title":"Remy Laure Soothing Cream kena batal notifikasi pada 24 Ogos 2026 sebab NPRA kesan hydroquinone dalam formula.","points":[]},{"title":"Hydroquinone ubat, bukan bahan kosmetik, dan ia dalam senarai larangan.","points":[]},{"title":"Nombor notifikasi keluar based on apa syarikat isytiharkan sendiri semasa hantar permohonan.","points":["NPRA tak uji kandungan sebelum produk sampai ke pasaran."]},{"title":"Ujian sebenar jalan lepas produk dah di pasaran, melalui sampling dan aduan.","points":[]},{"title":"Kalau kandungan tak match apa yang diisytiharkan, atau ada bahan larangan macam hydroquinone","points":["notifikasi boleh dibatalkan bila-bila masa, walaupun dah aktif bertahun."]},{"title":"Dan syarikat yang sama boleh notify semula produk lain esok, tanpa NPRA pernah semak formula itu pun.","points":[]}]'::jsonb, '2026-09-28'::date, '08:00', 'scheduled', '[{"hard":false,"where":"Slides","msg":"written but not drawn yet. Only drawn slides are sent."},{"hard":true,"where":"Post","msg":"instagram needs an image"}]'::jsonb, 1, '{"facebook":{"at":"2026-09-22 06:36 MYT","dueAt":"2026-09-28T00:00:00.000Z","id":"6ab1b16874d4ff403e12f028","mode":"customScheduled","route":"buffer-release","status":"scheduled","via":"ws.regulab Studio"},"instagram":{"at":"2026-09-22 06:36 MYT","dueAt":"2026-09-28T00:00:00.000Z","id":"6ab1b1761177eabccaf0ae84","mode":"customScheduled","route":"buffer-release","status":"scheduled","via":"ws.regulab Studio"},"threads":{"at":"2026-09-22 06:36 MYT","dueAt":"2026-09-28T00:00:00.000Z","id":"6ab1b182826cfc54b85d9c60","mode":"customScheduled","route":"buffer-release","status":"scheduled","via":"ws.regulab Studio"}}'::jsonb, null, null, '2026-09-20T16:44:57.725Z'::timestamptz) on conflict (id) do nothing;  -- y59n20rc7o (scheduled)
insert into public.semasa_posts (id, idea_id, stream, domain, angle, lang, hook, text, citation, slides, date, slot, status, flags, hard_flags, published, posted_at, archived_at, created_at) values ('79ade53c-56b1-5e4b-9684-73f1083c5bd9'::uuid, '7bd549dc-7c3f-5b53-8549-9632239acc1b'::uuid, 'regulab', 'halal_my', null, 'bm', 'Coca-Cola dan Pepsi dituduh ''mengandungi arak'' lagi. JAKIM dah jawab, tapi mesej lama tu masih tular.', '{"bm":{"instagram":"Mesej berantai lama pasal Coca-Cola dan Pepsi Cola ''sebenarnya arak'' tular balik minggu ni. JAKIM dah semak dan sahkan Coca-Cola dikilangkan oleh Coca-Cola Bottlers (Malaysia) Sdn Bhd, manakala Pepsi Cola oleh Syarikat Etika Sdn Bhd, dua-dua memegang Sijil Pengesahan Halal Malaysia yang sah. Dakwaan tu tersebar tanpa sesiapa usul periksa dulu.\n\nYang menarik untuk SME di sini: kalau jenama besar macam ni pun boleh jadi sasaran mesej tanpa sumber, produk anda yang baru nak bina nama lagi senang kena. Dan bila khabar angin macam ni sampai kat pelanggan anda, jawapan ''produk kami halal'' sahaja dah tak memadai. Orang dah biasa skeptikal lepas banyak kali kena tipu mesej WhatsApp.\n\nYang sebenarnya stop rumor daripada merebak ialah bila anda boleh bagi nombor sijil halal dan nama pengilang yang boleh disemak sendiri kat MYeHALAL. Bukan claim kosong, bukan ''percayalah kami''. Kalau rekod tu tak simpan handy sekarang, masa crisis datang anda takkan sempat cari.","facebook":"Mesej lama Coca-Cola dan Pepsi ''mengandungi arak'' tular semula. JAKIM dah sahkan Coca-Cola dikilangkan oleh Coca-Cola Bottlers (Malaysia) Sdn Bhd dan Pepsi Cola oleh Syarikat Etika Sdn Bhd, dua-dua ada Sijil Pengesahan Halal Malaysia yang sah.\n\nPengajaran untuk SME: jenama besar pun kena sasar mesej tanpa sumber. Jawapan ''produk kami halal'' je tak cukup lagi bila khabar angin sampai. Yang stop rumor ialah nombor sijil dan nama pengilang yang boleh disemak sendiri, bukan claim kosong.","threads":"Coca-Cola dan Pepsi dituduh ''mengandungi arak'' lagi. JAKIM dah sahkan dua-dua ada Sijil Pengesahan Halal Malaysia yang sah, dikilangkan oleh syarikat tempatan berdaftar. Kalau jenama sebesar ni pun kena sasar mesej tanpa sumber, ''produk kami halal'' je bukan jawapan yang cukup. Bawa nombor sijil dan nama pengilang, itu yang stop rumor."},"en":{"instagram":"An old chain message claiming Coca-Cola and Pepsi Cola ''actually contain alcohol'' is circulating again this week. JAKIM checked and confirmed Coca-Cola is manufactured by Coca-Cola Bottlers (Malaysia) Sdn Bhd, and Pepsi Cola by Syarikat Etika Sdn Bhd, both holding valid Sijil Pengesahan Halal Malaysia. The claim was spread without anyone checking first.\n\nWhat is worth noting for SME owners: if a brand this big can still get hit by a source-less chain message, a product you are still building trust for is an easier target. And when a rumour like this reaches your customers, saying ''our product is halal'' is no longer enough on its own. People have grown skeptical after too many WhatsApp hoaxes.\n\nWhat actually stops a rumour from spreading is when you can give the halal certificate number and the manufacturer''s name, something the reader can verify themselves on MYeHALAL. Not an empty claim, not ''trust us''. If that record is not kept handy now, you will not have time to dig it up when the crisis hits.","facebook":"An old chain message claiming Coca-Cola and Pepsi contain alcohol is going around again. JAKIM confirmed Coca-Cola is made by Coca-Cola Bottlers (Malaysia) Sdn Bhd and Pepsi Cola by Syarikat Etika Sdn Bhd, both holding valid Sijil Pengesahan Halal Malaysia.\n\nLesson for SMEs: even a global brand gets targeted by source-less rumours. ''Our product is halal'' alone is not enough once a rumour spreads. What stops it is the certificate number and manufacturer''s name, something people can verify themselves.","threads":"Coca-Cola and Pepsi are accused of ''containing alcohol'', again. JAKIM confirmed both hold valid Sijil Pengesahan Halal Malaysia, made by registered local manufacturers. If a brand this big still gets hit by a source-less rumour, ''it''s halal'' alone is not a real answer. The certificate number and manufacturer''s name are what actually stop it."}}'::jsonb, '[SAHKAN: tarikh dan rujukan kenyataan rasmi JAKIM tentang dakwaan Coca-Cola/Pepsi Cola mengandungi arak -- semak portal rasmi halal.gov.my dan kenyataan media JAKIM]', '[]'::jsonb, '2026-10-03'::date, '08:00', 'draft', '[{"hard":true,"where":"Post","msg":"instagram needs an image"}]'::jsonb, 1, '{}'::jsonb, null, null, '2026-09-25T03:45:52.933Z'::timestamptz) on conflict (id) do nothing;  -- yjdoa64p3x (draft)
insert into public.semasa_posts (id, idea_id, stream, domain, angle, lang, hook, text, citation, slides, date, slot, status, flags, hard_flags, published, posted_at, archived_at, created_at) values ('93feeca8-e545-5afd-bdd6-26341944f383'::uuid, '3323e47f-e52a-5d73-a712-9b62b931ac78'::uuid, 'regulab', 'sains_kosmetik', null, 'bm', 'Bahan ''postbiotic'' pada label bukan automatik selamat sebab ia dari bakteria baik.', '{"bm":{"instagram":"Ramai brand letak ''postbiotic'' atau ''MDV'' (microbiome-derived vesicle) pada label dan anggap ia automatik selamat sebab sumbernya bakteria baik. Logik tu tak tepat.\n\nKajian dalam jurnal Genes & Genomics (terbit 9 September 2026) jelaskan MDV menarik dalam formulasi sebab ia bioaktif secara biologi, bukan sebab ia lembut atau tak berbahaya. Bahan yang bioaktif boleh beri kesan kuat pada kulit atau badan, sama macam bahan aktif lain. Keselamatan dan keberkesanannya bergantung pada tiga benda: sumber bakteria itu boleh disahkan secara genomik, proses pembuatan boleh diulang secara konsisten, dan bukti yang dibawa setimpal dengan dakwaan yang dibuat.\n\nUntuk brand tempatan yang baru mula guna bahan jenis ni daripada pembekal, soalan yang patut ditanya bukan ''ia dari probiotic ke tak''. Soalan sebenar: pembekal boleh tunjuk certificate of analysis yang sahkan sumber genomik bakteria tu, dan ada kawalan kualiti yang konsisten dari satu batch ke batch seterusnya?\n\nKalau pembekal tak boleh jawab dua benda ni dengan dokumen, bukan cerita, itu dah cukup jadi red flag sebelum anda letak dalam formulasi.","facebook":"Postbiotic atau MDV pada label bukan automatik selamat sebab ''dari bakteria baik''. Kajian dalam Genes & Genomics (9 Sept 2026) sebut MDV menarik sebab ia bioaktif, bukan sebab ia lembut.\n\nKeselamatan bergantung pada sumber bakteria yang boleh disahkan secara genomik dan proses pembuatan yang konsisten setiap batch.\n\nUntuk brand yang guna bahan ni daripada pembekal: jangan tanya ''dari probiotic ke tak''. Tanya sama ada mereka ada bukti genomik dan QC konsisten setiap batch.","threads":"Postbiotic/MDV pada label tak automatik selamat sebab ''dari bakteria baik''. Kajian Genes & Genomics (9 Sept 2026): ia menarik sebab bioaktif, bukan sebab lembut. Soalan betul untuk pembekal: ada bukti genomik sumber bakteria, dan QC konsisten setiap batch?"},"en":{"instagram":"A lot of brands slap ''postbiotic'' or ''MDV'' (microbiome-derived vesicle) on the label and assume it''s automatically safe because it comes from good bacteria. That logic doesn''t hold.\n\nA study in Genes & Genomics (published 9 September 2026) makes the point that MDVs are interesting precisely because they are biologically bioactive, not because they''re gentle or harmless. Bioactive means it can produce a real effect on skin or body, same as any other active ingredient. Safety and efficacy come down to three things: whether the bacterial source has verifiable genomic provenance, whether the manufacturing process is reproducible, and whether the evidence actually matches the claims being made.\n\nFor local brands starting to use this class of active from a supplier, the right question isn''t ''is it from probiotics''. The right question is whether the supplier can show genomic sourcing documentation and consistent batch-to-batch quality control.\n\nIf they can''t answer both with paperwork instead of a story, that''s a red flag before it ever goes into your formulation.","facebook":"Postbiotic or MDV on a label doesn''t mean automatically safe just because it''s ''from good bacteria''. A study in Genes & Genomics (9 Sept 2026) points out MDVs matter because they''re bioactive, not because they''re gentle.\n\nSafety depends on verified genomic provenance of the bacterial source and consistent batch-to-batch manufacturing.\n\nIf you''re sourcing this from a supplier, don''t ask if it''s probiotic-derived. Ask for genomic proof and batch QC data.","threads":"Postbiotic/MDV on a label isn''t automatically safe just because it''s ''from good bacteria''. Genes & Genomics study (9 Sept 2026): it matters because it''s bioactive, not gentle. Right question for suppliers: genomic sourcing proof and consistent batch QC, not just ''is it probiotic''."}}'::jsonb, 'Genes & Genomics journal, article on microbiome-derived vesicles, published 9 September 2026', '[]'::jsonb, '2026-10-02'::date, '13:00', 'draft', '[{"hard":true,"where":"Post","msg":"instagram needs an image"}]'::jsonb, 1, '{}'::jsonb, null, null, '2026-09-22T08:23:45.643Z'::timestamptz) on conflict (id) do nothing;  -- z38x3dqhw6 (draft)
